window.KH_SURA(36, {"sura": "يس", "n": 36, "ayat": {"1": "يس", "2": "وَالْقُرْآنِ الْحَكِيمِ", "3": "إِنَّكَ لَمِنَ الْمُرْسَلِينَ", "4": "عَلَى صِرَاطٍ مُسْتَقِيمٍ", "5": "تَنْزِيلَ الْعَزِيزِ الرَّحِيمِ", "6": "لِتُنْذِرَ قَوْمًا مَا أُنْذِرَ آبَاؤُهُمْ فَهُمْ غَافِلُونَ", "7": "لَقَدْ حَقَّ الْقَوْلُ عَلَى أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ", "8": "إِنَّا جَعَلْنَا فِي أَعْنَاقِهِمْ أَغْلَالًا فَهِيَ إِلَى الْأَذْقَانِ فَهُمْ مُقْمَحُونَ", "9": "وَجَعَلْنَا مِنْ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَاهُمْ فَهُمْ لَا يُبْصِرُونَ", "10": "وَسَوَاءٌ عَلَيْهِمْ أَأَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لَا يُؤْمِنُونَ", "11": "إِنَّمَا تُنْذِرُ مَنِ اتَّبَعَ الذِّكْرَ وَخَشِيَ الرَّحْمَنَ بِالْغَيْبِ فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ", "12": "إِنَّا نَحْنُ نُحْيِ الْمَوْتَى وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ فِي إِمَامٍ مُبِينٍ", "13": "وَاضْرِبْ لَهُمْ مَثَلًا أَصْحَابَ الْقَرْيَةِ إِذْ جَاءَهَا الْمُرْسَلُونَ", "14": "إِذْ أَرْسَلْنَا إِلَيْهِمُ اثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوا إِنَّا إِلَيْكُمْ مُرْسَلُونَ", "15": "قَالُوا مَا أَنْتُمْ إِلَّا بَشَرٌ مِثْلُنَا وَمَا أَنْزَلَ الرَّحْمَنُ مِنْ شَيْءٍ إِنْ أَنْتُمْ إِلَّا تَكْذِبُونَ", "16": "قَالُوا رَبُّنَا يَعْلَمُ إِنَّا إِلَيْكُمْ لَمُرْسَلُونَ", "17": "وَمَا عَلَيْنَا إِلَّا الْبَلَاغُ الْمُبِينُ", "18": "قَالُوا إِنَّا تَطَيَّرْنَا بِكُمْ لَئِنْ لَمْ تَنْتَهُوا لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُمْ مِنَّا عَذَابٌ أَلِيمٌ", "19": "قَالُوا طَائِرُكُمْ مَعَكُمْ أَئِنْ ذُكِّرْتُمْ بَلْ أَنْتُمْ قَوْمٌ مُسْرِفُونَ", "20": "وَجَاءَ مِنْ أَقْصَى الْمَدِينَةِ رَجُلٌ يَسْعَى قَالَ يَاقَوْمِ اتَّبِعُوا الْمُرْسَلِينَ", "21": "اتَّبِعُوا مَنْ لَا يَسْأَلُكُمْ أَجْرًا وَهُمْ مُهْتَدُونَ", "22": "وَمَا لِيَ لَا أَعْبُدُ الَّذِي فَطَرَنِي وَإِلَيْهِ تُرْجَعُونَ", "23": "أَأَتَّخِذُ مِنْ دُونِهِ آلِهَةً إِنْ يُرِدْنِ الرَّحْمَنُ بِضُرٍّ لَا تُغْنِ عَنِّي شَفَاعَتُهُمْ شَيْئًا وَلَا يُنْقِذُونِ", "24": "إِنِّي إِذًا لَفِي ضَلَالٍ مُبِينٍ", "25": "إِنِّي آمَنْتُ بِرَبِّكُمْ فَاسْمَعُونِ", "26": "قِيلَ ادْخُلِ الْجَنَّةَ قَالَ يَالَيْتَ قَوْمِي يَعْلَمُونَ", "27": "بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ الْمُكْرَمِينَ", "28": "وَمَا أَنْزَلْنَا عَلَى قَوْمِهِ مِنْ بَعْدِهِ مِنْ جُنْدٍ مِنَ السَّمَاءِ وَمَا كُنَّا مُنْزِلِينَ", "29": "إِنْ كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ خَامِدُونَ", "30": "يَاحَسْرَةً عَلَى الْعِبَادِ مَا يَأْتِيهِمْ مِنْ رَسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ", "31": "أَلَمْ يَرَوْا كَمْ أَهْلَكْنَا قَبْلَهُمْ مِنَ الْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ", "32": "وَإِنْ كُلٌّ لَمَّا جَمِيعٌ لَدَيْنَا مُحْضَرُونَ", "33": "وَآيَةٌ لَهُمُ الْأَرْضُ الْمَيْتَةُ أَحْيَيْنَاهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ", "34": "وَجَعَلْنَا فِيهَا جَنَّاتٍ مِنْ نَخِيلٍ وَأَعْنَابٍ وَفَجَّرْنَا فِيهَا مِنَ الْعُيُونِ", "35": "لِيَأْكُلُوا مِنْ ثَمَرِهِ وَمَا عَمِلَتْهُ أَيْدِيهِمْ أَفَلَا يَشْكُرُونَ", "36": "سُبْحَانَ الَّذِي خَلَقَ الْأَزْوَاجَ كُلَّهَا مِمَّا تُنْبِتُ الْأَرْضُ وَمِنْ أَنْفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ", "37": "وَآيَةٌ لَهُمُ اللَّيْلُ نَسْلَخُ مِنْهُ النَّهَارَ فَإِذَا هُمْ مُظْلِمُونَ", "38": "وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ", "39": "وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتَّى عَادَ كَالْعُرْجُونِ الْقَدِيمِ", "40": "لَا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ وَلَا اللَّيْلُ سَابِقُ النَّهَارِ وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ", "41": "وَآيَةٌ لَهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِي الْفُلْكِ الْمَشْحُونِ", "42": "وَخَلَقْنَا لَهُمْ مِنْ مِثْلِهِ مَا يَرْكَبُونَ", "43": "وَإِنْ نَشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنْقَذُونَ", "44": "إِلَّا رَحْمَةً مِنَّا وَمَتَاعًا إِلَى حِينٍ", "45": "وَإِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ", "46": "وَمَا تَأْتِيهِمْ مِنْ آيَةٍ مِنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ", "47": "وَإِذَا قِيلَ لَهُمْ أَنْفِقُوا مِمَّا رَزَقَكُمُ اللَّهُ قَالَ الَّذِينَ كَفَرُوا لِلَّذِينَ آمَنُوا أَنُطْعِمُ مَنْ لَوْ يَشَاءُ اللَّهُ أَطْعَمَهُ إِنْ أَنْتُمْ إِلَّا فِي ضَلَالٍ مُبِينٍ", "48": "وَيَقُولُونَ مَتَى هَذَا الْوَعْدُ إِنْ كُنْتُمْ صَادِقِينَ", "49": "مَا يَنْظُرُونَ إِلَّا صَيْحَةً وَاحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ", "50": "فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَا إِلَى أَهْلِهِمْ يَرْجِعُونَ", "51": "وَنُفِخَ فِي الصُّورِ فَإِذَا هُمْ مِنَ الْأَجْدَاثِ إِلَى رَبِّهِمْ يَنْسِلُونَ", "52": "قَالُوا يَاوَيْلَنَا مَنْ بَعَثَنَا مِنْ مَرْقَدِنَا هَذَا مَا وَعَدَ الرَّحْمَنُ وَصَدَقَ الْمُرْسَلُونَ", "53": "إِنْ كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ جَمِيعٌ لَدَيْنَا مُحْضَرُونَ", "54": "فَالْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْئًا وَلَا تُجْزَوْنَ إِلَّا مَا كُنْتُمْ تَعْمَلُونَ", "55": "إِنَّ أَصْحَابَ الْجَنَّةِ الْيَوْمَ فِي شُغُلٍ فَاكِهُونَ", "56": "هُمْ وَأَزْوَاجُهُمْ فِي ظِلَالٍ عَلَى الْأَرَائِكِ مُتَّكِئُونَ", "57": "لَهُمْ فِيهَا فَاكِهَةٌ وَلَهُمْ مَا يَدَّعُونَ", "58": "سَلَامٌ قَوْلًا مِنْ رَبٍّ رَحِيمٍ", "59": "وَامْتَازُوا الْيَوْمَ أَيُّهَا الْمُجْرِمُونَ", "60": "أَلَمْ أَعْهَدْ إِلَيْكُمْ يَابَنِي آدَمَ أَنْ لَا تَعْبُدُوا الشَّيْطَانَ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ", "61": "وَأَنِ اعْبُدُونِي هَذَا صِرَاطٌ مُسْتَقِيمٌ", "62": "وَلَقَدْ أَضَلَّ مِنْكُمْ جِبِلًّا كَثِيرًا أَفَلَمْ تَكُونُوا تَعْقِلُونَ", "63": "هَذِهِ جَهَنَّمُ الَّتِي كُنْتُمْ تُوعَدُونَ", "64": "اصْلَوْهَا الْيَوْمَ بِمَا كُنْتُمْ تَكْفُرُونَ", "65": "الْيَوْمَ نَخْتِمُ عَلَى أَفْوَاهِهِمْ وَتُكَلِّمُنَا أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُمْ بِمَا كَانُوا يَكْسِبُونَ", "66": "وَلَوْ نَشَاءُ لَطَمَسْنَا عَلَى أَعْيُنِهِمْ فَاسْتَبَقُوا الصِّرَاطَ فَأَنَّى يُبْصِرُونَ", "67": "وَلَوْ نَشَاءُ لَمَسَخْنَاهُمْ عَلَى مَكَانَتِهِمْ فَمَا اسْتَطَاعُوا مُضِيًّا وَلَا يَرْجِعُونَ", "68": "وَمَنْ نُعَمِّرْهُ نُنَكِّسْهُ فِي الْخَلْقِ أَفَلَا يَعْقِلُونَ", "69": "وَمَا عَلَّمْنَاهُ الشِّعْرَ وَمَا يَنْبَغِي لَهُ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْآنٌ مُبِينٌ", "70": "لِيُنْذِرَ مَنْ كَانَ حَيًّا وَيَحِقَّ الْقَوْلُ عَلَى الْكَافِرِينَ", "71": "أَوَلَمْ يَرَوْا أَنَّا خَلَقْنَا لَهُمْ مِمَّا عَمِلَتْ أَيْدِينَا أَنْعَامًا فَهُمْ لَهَا مَالِكُونَ", "72": "وَذَلَّلْنَاهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ", "73": "وَلَهُمْ فِيهَا مَنَافِعُ وَمَشَارِبُ أَفَلَا يَشْكُرُونَ", "74": "وَاتَّخَذُوا مِنْ دُونِ اللَّهِ آلِهَةً لَعَلَّهُمْ يُنْصَرُونَ", "75": "لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُنْدٌ مُحْضَرُونَ", "76": "فَلَا يَحْزُنْكَ قَوْلُهُمْ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ", "77": "أَوَلَمْ يَرَ الْإِنْسَانُ أَنَّا خَلَقْنَاهُ مِنْ نُطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُبِينٌ", "78": "وَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ قَالَ مَنْ يُحْيِ الْعِظَامَ وَهِيَ رَمِيمٌ", "79": "قُلْ يُحْيِيهَا الَّذِي أَنْشَأَهَا أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ", "80": "الَّذِي جَعَلَ لَكُمْ مِنَ الشَّجَرِ الْأَخْضَرِ نَارًا فَإِذَا أَنْتُمْ مِنْهُ تُوقِدُونَ", "81": "أَوَلَيْسَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِقَادِرٍ عَلَى أَنْ يَخْلُقَ مِثْلَهُمْ بَلَى وَهُوَ الْخَلَّاقُ الْعَلِيمُ", "82": "إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ", "83": "فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ"}, "units": [{"aya": 1, "title": "في تأويل قوله: ﴿يس﴾", "tabari": {"page": "19/398", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هو قسم أقسم الله به، وهو من أسماء الله ﷿", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [64286, 64289, 64290, 64291, 64292]}, {"n": 2, "t": "معناه: يا رجل", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"]], "athar": [64286, 64289, 64290, 64291, 64292]}, {"n": 3, "t": "هو مفتاح كلام افتتح الله به كلامه", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [64298]}, {"n": 4, "t": "بل هو اسم من أسماء القرآن", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [64304, 64305]}]}, "mawaqif": [], "mushid": {"i": 1, "imgs": ["036_001_1.png"], "pages": [429], "n": 4, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 6, "title": "في تأويل قوله: ﴿لتنذر قوما ما أنذر آباؤهم﴾", "tabari": {"page": "19/401", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه: لتنذر قوما ما أنذر الله من قبلهم من آبائهم", "taqdim": 0, "n_athar": 1, "qailun": [["عكرمة في هذه الآية", "تابعي"]], "athar": []}, {"n": 2, "t": "بل معنى ذلك: لتنذر قوما [لم ينذر] آباؤهم", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [64318, 64319]}]}, "mawaqif": [], "mushid": {"i": 2, "imgs": ["036_002_1.png"], "pages": [429], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 6, "title": "في معنى ﴿ما﴾ التي في قوله: ﴿ما أنذر آباؤهم﴾. إذا وجه معنى الكلام إلى أن آباءهم قد كانوا أنذروا، ولم يرد بها الجحد", "tabari": {"page": "19/402", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معنى ذلك - إذا أريد به غير الجحد -: لتنذرهم الذي أنذر آباؤهم فهم غافلون. وقال: ودخول الفاء في هذا المعنى لا يجوز، والله أعلم. قال: وهو على الجحد أحسن، فيكون معنى الكلام: إنك لمن المرسلين إلى قوم لم ينذر آباؤهم؛ لأنهم كانوا في الفترة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إذا لم يرد ب \"ما\" الجحد، فإن معنى الكلام: لتنذرهم بما أنذر آباؤهم. فتلقى الباء، فتكون \"ما\" في موضع نصب: [كما قال: ﴿أنذرتكم صاعقة مثل صاعقة عاد وثمود﴾ [فصلت: ١٣]", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 12, "title": "قوله: {وآثارهم}", "mawsua": {"taliq": 5406, "masala": "قوله: {وآثارهم}", "sigha": "ذكر قولين", "nasib": "ابن كثير", "aqwal": [{"n": 1, "t": "أنها الأعمال التي عملوها في حياتهم، وآثارها بعد مماتهم", "ashab": "", "athar": []}, {"n": 2, "t": "أنها الخطا إلى المساجد. وقال عقب ذكره القول الثاني: «وهذا القول لا تنافي بينه وبين الأول، بل في هذا تنبيه ودلالة على ذلك بطريق الأولى والأحرى، فإنه إذا كانت هذه الآثار تكتب فلأن تكتب تلك التي فيها قدوة بهم من خير أو شر بطريق الأولى", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5406, "mi": 1, "aya": 12, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 348 - 350", "qawl": "الثاني", "nass": "وهذا القول لا تنافي بينه وبين الأول، بل في هذا تنبيه ودلالة على ذلك بطريق الأولى والأحرى، فإنه إذا كانت هذه الآثار تكتب فلأن تكتب تلك التي فيها قدوة بهم من خير أو شر بطريق الأولى", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 13, "title": "في هؤلاء الرسل، وفيمن كان أرسلهم إلى أصحاب القرية", "tabari": {"page": "19/413", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "كانوا رسل عيسى ابن مريم، وعيسى الذي كان أرسلهم إليهم", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"], ["عكرمة", "تابعي"]], "athar": [64431, 64439]}, {"n": 2, "t": "بل كانوا رسلا من عند الله أرسلهم الله إليهم", "taqdim": 0, "n_athar": 1, "qailun": [["وهب بن منبه", "تابعي"]], "athar": [64438]}]}, "mawaqif": [{"taliq": 5410, "mi": 0, "aya": 14, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "19/ 415 بتصرف", "qawl": "", "nass": "وبالتشديد في قوله: {فعززنا} قرأت القراء سوى عاصم، فإنه قرأه بالتخفيف، وأن معناه إذا شدد: فقوينا، وإذا خفف: فغلبنا، وليس لغلبنا في هذا الموضع كثير معنى", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 5410, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "7/ 239", "qawl": "", "nass": "غلبناهم أمرهم", "qawaid": [], "tabi": ""}], "mushid": {"i": 3, "imgs": ["036_003_1.png"], "pages": [429], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 13, "title": "قوله: {إذ جاءها المرسلون}", "mawsua": {"taliq": 5409, "masala": "قوله: {إذ جاءها المرسلون}", "sigha": "ذكر قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنهم من الحواريين. كما في قول قتادة", "ashab": "", "athar": []}, {"n": 2, "t": "أنهم أنبياء من قبل الله", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5409, "mi": 1, "aya": 13, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 239", "qawl": "قتادة", "nass": "وهذا يرجحه قول الكفرة: {ما أنتم إلا بشر مثلنا}؛ فإنها محاورة إنما تقال لمن ادعى الرسالة عن الله تعالى", "qawaid": [], "tabi": ""}, {"taliq": 5409, "mi": 1, "aya": 13, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 318 - 323", "qawl": "", "nass": "رسل الله", "qawaid": ["التاريخ والواقع", "ظاهر الآية ولفظها", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5409, "mi": 1, "aya": 13, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "11/ 257", "qawl": "الأول", "nass": "ظاهر القصة يدل على أن هؤلاء كانوا رسل الله عز وجل، لا من جهة المسيح، كما قال تعالى: {إذ أرسلنا إليهم اثنين فكذبوهما فعززنا بثالث فقالوا إنا إليكم مرسلون} إلى أن قالوا: {ربنا يعلم إنا إليكم لمرسلون * وما علينا إلا البلاغ المبين} [يس: 14 - 17]. ولو كان هؤلاء من الحواريين لقالوا عبارة تناسب أنهم من عند المسيح، عليه السلام، والله أعلم. ثم لو كانوا رسل المسيح لما قالوا لهم: {ما أنتم إلا بشر مثلنا}", "qawaid": ["الدلالة العقلية", "ظاهر الآية ولفظها"], "tabi": ""}], "tags": {"m": {"1": [["ابن كثير", "d"]]}, "t": {}, "gen": [["ابن تيمية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن تيمية": ["التاريخ والواقع", "ظاهر الآية ولفظها", "الدلالة العقلية"]}, "rulesD": {"ابن كثير": ["الدلالة العقلية", "ظاهر الآية ولفظها"]}}}, {"aya": 25, "title": "تأويل: ﴿إني آمنت بربكم فاسمعون﴾", "tabari": {"page": "19/423", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿إني آمنت بربكم فاسمعون﴾. اختلف في معنى ذلك؛ فقال بعضهم: قال هذا القول هذا المؤمن لقومه، يعلمهم إيمانه بالله.", "taqdim": 1, "n_athar": 1, "qailun": [["وهب بن منبه", "تابعي"]], "athar": [64528, 64531]}, {"n": 2, "t": "بل خاطب بذلك الرسل وقال لهم: اسمعوا قولى، لتشهدوا لى بما أقول لكم عند ربي، وأنى قد آمنت بكم واتبعتكم. فذكر أنه لما قال هذا القول، ونصح لقومه النصيحة التي ذكرها الله في كتابه، وثبوا عليه فقتلوه", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5418, "mi": 1, "aya": 25, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "11/ 254 بتصرف", "qawl": "الثاني", "nass": "وهذا أظهر في المعنى", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "mushid": {"i": 4, "imgs": ["036_004_1.png", "036_004_2.png"], "pages": [429, 430], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5418, "masala": "قوله: {فاسمعون}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "أنه خطاب منه لقومه", "ashab": "", "athar": []}, {"n": 2, "t": "أنه خطاب للرسل", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن كثير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن كثير": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 25, "title": "في صفة قتلهم إياه", "tabari": {"page": "19/423", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "رجموه بالحجارة", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [64532]}, {"n": 2, "t": "بل وثبوا عليه، فوطئوه بأقدامهم حتى مات", "taqdim": 0, "n_athar": 2, "qailun": [["وهب بن منبه", "تابعي"], ["بعض أصحابه", ""]], "athar": [64528, 64531]}]}, "mawaqif": [], "mushid": {"i": 5, "imgs": ["036_005_1.png"], "pages": [430], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 26, "title": "قوله: {يا ليت قومي يعلمون}", "mawsua": {"taliq": 5419, "masala": "قوله: {يا ليت قومي يعلمون}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أراد بذلك الإشفاق والنصح لهم، أي: لو علموا بذلك لآمنوا بالله تعالى", "ashab": "", "athar": []}, {"n": 2, "t": "أراد أن يعلموا ذلك، فيندموا على فعلهم به، ويحزنهم ذلك، وهذا موجود في جبلة البشر إذا نال خيرا في بلد غربة ود أن يعلم ذلك جيرانه وأترابه الذين نشأ فيهم، ولا سيما في الكرامات، ونحو من ذلك قول الشاعر:", "ashab": "", "athar": []}, {"n": 3, "t": "نصحهم على حالة الغضب والرضى، وكذلك لا تجد المؤمن إلا ناصحا للناس", "ashab": "قتادة بن دعامة", "athar": [64539, 64540]}]}, "mawaqif": [{"taliq": 5419, "mi": 1, "aya": 26, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 243", "qawl": "الشاعر", "nass": "والتأويل الأول أشبه بهذا العبد الصالح، وفي ذلك قال النبي صلى الله عليه وسلم: «نصح قومه حيا وميتا", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 28, "title": "في معنى الجند الذي أخبر الله أنه لم ينزل إلى قوم هذا المؤمن بعد قتلهموه", "tabari": {"page": "19/426", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى بذلك أنه لم ينزل الله بعد ذلك إليهم رسالة، ولا بعث إليهم نبيا", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [64544, 64547]}, {"n": 2, "t": "بل عنى بذلك أن الله تعالى ذكره لم يبعث لهم جنودا يقاتلهم بها، ولكنه أهلكهم بصيحة واحدة", "taqdim": 0, "n_athar": 1, "qailun": [["بعض أصحابه", ""]], "athar": []}]}, "mawaqif": [{"taliq": 5420, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 428", "qawl": "الثاني", "nass": "وهذا القول الثاني أولى القولين بتأويل الآية، وذلك أن الرسالة لا يقال لها: جند، إلا أن يكون أراد مجاهد بذلك: الرسل، فيكون وجها، وإن كان أيضا من المفهوم بظاهر الآية بعيدا، وذلك أن الرسل من بني آدم لا ينزلون من السماء، والخبر في ظاهر هذه الآية عن أنه لم ينزل من السماء بعد مهلك هذا المؤمن على قومه جندا، وذلك بالملائكة أشبه منه ببني آدم", "qawaid": ["اللغة", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5420, "mi": 1, "aya": 28, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 244", "qawl": "", "nass": "ما", "qawaid": [], "tabi": ""}], "mushid": {"i": 6, "imgs": ["036_006_1.png"], "pages": [430], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 5420, "masala": "ما عنى الله بالجند", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها الرسالة", "ashab": "مجاهد", "athar": [64544]}, {"n": 2, "t": "أن معنى ذلك: أن الله لم يبعث لهم جنودا يقاتلهم بها، ولكنه أهلكهم بصيحة واحدة", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 38, "title": "تأويل: ﴿والشمس تجري لمستقر لها﴾", "tabari": {"page": "19/435", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿والشمس تجري لمستقر لها﴾. يقول تعالى ذكره: والشمس تجرى لموضع قرارها. بمعنى: إلى موضع قرارها. وبذلك جاء الأثر عن رسول الله ﷺ.", "taqdim": 1, "n_athar": 1, "qailun": [["أبي ذر الغفاري", "صحابي"]], "athar": [64617]}, {"n": 2, "t": "ثنا يزيد، قال: ثنا سعيد، عن قتادة قوله: ﴿والشمس تجري لمستقر لها﴾. قال: وقت واحد لا تعدوه", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "معنى ذلك: تجرى لمجرى لها إلى مقادير مواضعها. بمعنى أنها تجرى إلى أبعد منازلها في الغروب، ثم ترجع ولا تجاوزه. قالوا: وذلك أنها لا تزال تتقدم كل ليلة، حتى تنتهي إلى أبعد مغاربها، ثم ترجع", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 7, "imgs": ["036_007_1.png"], "pages": [430], "n": 3, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 42, "title": "في الذي عنى بقوله: ﴿ما يركبون﴾", "tabari": {"page": "19/444", "sarih": 1, "tarjih": "وأشبه القولين بتأويل ذلك قول من قال: عنى بذلك السفن. وذلك لدلالة قوله: ﴿وإن نشأ نغرقهم فلا صريخ لهم﴾. على أن ذلك كذلك، وذلك أن الغرق معلوم أنه لا يكون إلا في الماء، ولا غرق في البر.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "هي السفن", "taqdim": 0, "n_athar": 9, "qailun": [["ابن عباس", "صحابي"], ["أبي مالك", "تابعي"], ["الحسن في هذه الآية", "تابعي"], ["أبي صالح", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [64688, 64689, 64694, 64695, 64698, 64699, 64700, 64701, 64703]}, {"n": 2, "t": "بل عنى بذلك الإبل", "taqdim": 0, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"], ["السدي", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [64688, 64689, 64691, 64700, 64701]}]}, "mawaqif": [{"taliq": 5433, "mi": 1, "aya": 42, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 446 - 447", "qawl": "الأول", "nass": "وأشبه القولين بتأويل ذلك قول من قال: عني بذلك: السفن، وذلك لدلالة قوله: {وإن نشأ نغرقهم فلا صريخ لهم} [يس: 43]، على أن ذلك كذلك، وذلك أن الغرق معلوم أن لا يكون إلا في الماء، ولا غرق في البر", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5433, "mi": 1, "aya": 42, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 250 - 251", "qawl": "", "nass": "وأما معنى الآية فيحتمل تأويلين: أحدهما قاله ابن عباس وجماعة، وهو أن يريد بالذريات المحمولين: أصحاب نوح في السفينة، ويريد بقوله: {من مثله}: السفن الموجودة في جنس بني آدم إلى يوم القيامة، وإياها أراد الله تعالى بقوله: {وإن نشأ نغرقهم}، والتأويل الثاني قاله مجاهد والسدي، وروي عن ابن عباس أيضا، هو أن يريد بقوله: {أنا حملنا ذريتهم في الفلك المشحون}: السفن الموجودة في بني آدم إلى يوم القيامة، ويريد بقوله: {وخلقنا لهم من مثله ما يركبون}: الإبل وسائر ما يركب، فتكون المماثلة في أنه مركوب مبلغ إلى الأقطار فقط، ويعود قوله: {وإن نشأ نغرقهم} على السفن الموجودة في الناس، وأما من خلط القولين فجعل الذرية في الفلك في قوم نوح في سفينة، وجعل {من مثله} في الإبل؛ فإن هذا نظر فاسد يقطع به قوله تعالى: {وإن نشأ نغرقهم}. فتأمله", "qawaid": [], "tabi": ""}], "mushid": {"i": 9, "imgs": ["036_009_1.png"], "pages": [431], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5433, "masala": "قوله: {وخلقنا لهم من مثله ما يركبون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه السفن", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الإبل", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 47, "title": "قوله: {إن أنتم إلا في ضلال مبين}", "mawsua": {"taliq": 5435, "masala": "قوله: {إن أنتم إلا في ضلال مبين}", "sigha": "ذكر وجهين", "nasib": "ابن جرير", "aqwal": [{"n": 1, "t": "أن يكون من قيل الكفار للمؤمنين، فيكون تأويل الكلام حينئذ: ما أنتم -أيها القوم- في قيلكم لنا: أنفقوا مما رزقكم الله على مساكينكم. إلا في ذهاب عن الحق، وجور عن الرشد، مبين لمن تأمله وتدبره أنه في ضلال. وهذا أولى وجهيه بتأويله", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون ذلك من قيل الله للمشركين، فيكون تأويله حينئذ: ما أنتم -أيها الكافرون- في قيلكم للمؤمنين: أنطعم من لو يشاء الله أطعمه. إلا في ضلال مبين عن أن قيلكم ذلك لهم ضلال", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5435, "mi": 1, "aya": 47, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 450", "qawl": "", "nass": "وفي قوله: {إن أنتم إلا في ضلال مبين} وجهان: أحدهما: أن يكون من قيل الكفار للمؤمنين، فيكون تأويل الكلام حينئذ: ما أنتم -أيها القوم- في قيلكم لنا: أنفقوا مما رزقكم الله على مساكينكم. إلا في ذهاب عن الحق، وجور عن الرشد، مبين لمن تأمله وتدبره أنه في ضلال. وهذا أولى وجهيه بتأويله. والوجه الآخر: أن يكون ذلك من قيل الله للمشركين، فيكون تأويله حينئذ: ما أنتم -أيها الكافرون- في قيلكم للمؤمنين: أنطعم من لو يشاء الله أطعمه. إلا في ضلال مبين عن أن قيلكم ذلك لهم ضلال", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 5435, "mi": 1, "aya": 47, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "7/ 253", "qawl": "", "nass": "", "qawaid": ["لم يذكر مستندًا"], "tabi": "ابن جرير"}, {"taliq": 5435, "mi": 1, "aya": 47, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "11/ 367", "qawl": "الثاني", "nass": "وفي هذا نظر", "qawaid": [], "tabi": ""}], "tags": {"m": {"2": [["ابن كثير", "d"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 52, "title": "تأويل: ﴿قالوا ياويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون﴾", "tabari": {"page": "19/458", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿قالوا ياويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون﴾. يقول تعالى ذكره: قال هؤلاء المشركون لما نفخ في الصور نفخة البعث لموقف القيامة، فردت أرواحهم إلى أجسامهم، وذلك بعد نومة ناموها: ﴿ياويلنا من بعثنا من مرقدنا﴾. وقد قيل: إن ذلك نومة بين النفختين.", "taqdim": 1, "n_athar": 6, "qailun": [["أبى بن كعب", "صحابي"], ["رجل يقال له", ""], ["قتادة", "تابعي"], ["مجاهد", "تابعي"]], "athar": [64767, 64771, 64772, 64773, 64776, 64777, 64782, 64783, 64785, 64786]}, {"n": 2, "t": "بل كلا القولين -أعنى: ﴿ياويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون﴾ - من قول الكفار", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد فى", "تابع التابعين"]], "athar": []}]}, "mawaqif": [{"taliq": 5440, "mi": 1, "aya": 52, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 458", "qawl": "الأول", "nass": "والقول الأول أشبه بظاهر التنزيل، وهو أن يكون من كلام المؤمنين؛ لأن الكفار في قيلهم: {من بعثنا من مرقدنا} دليل على أنهم كانوا بمن بعثهم من مرقدهم جهالا، ولذلك من جهلهم استثبتوا، ومحال أن يكونوا استثبتوا ذلك إلا من غيرهم ممن خالفت صفته صفتهم في ذلك", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5440, "mi": 1, "aya": 52, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "11/ 368", "qawl": "الأول", "nass": "وهو أصح، وذلك كقوله تعالى في الصافات: {وقالوا يا ويلنا هذا يوم الدين هذا يوم الفصل الذي كنتم به تكذبون} [الصافات: 20 - 21]، وقال الله تعالى: {ويوم تقوم الساعة يقسم المجرمون ما لبثوا غير ساعة كذلك كانوا يؤفكون * وقال الذين أوتوا العلم والإيمان لقد لبثتم في كتاب الله إلى يوم البعث فهذا يوم البعث ولكنكم كنتم لا تعلمون} [الروم: 55 - 56]", "qawaid": ["القرآن والنظائر"], "tabi": "ابن جرير"}, {"taliq": 5440, "mi": 1, "aya": 52, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "الأول", "nass": "ولا منافاة؛ إذ الجمع ممكن", "qawaid": [], "tabi": ""}], "mushid": {"i": 11, "imgs": ["036_011_1.png"], "pages": [431], "n": 0, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 5440, "masala": "قائل هذه المقالة: {هذا ما وعد الرحمن وصدق المرسلون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنهم المؤمنون", "ashab": "", "athar": []}, {"n": 2, "t": "أنهم الكفار", "ashab": "", "athar": []}, {"n": 3, "t": "أنهم الملائكة", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"], "ابن كثير": ["القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 55, "title": "في معنى الشغل الذى وصف الله جل ثناؤه أصحاب الجنة أنهم فيه يوم القيامة", "tabari": {"page": "19/459", "sarih": 1, "tarjih": "والصواب من القراءة فى ذلك عندى قراءة من قرأه بالألف ؛ لأن ذلك هو القراءة المعروفة.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "ذلك افتضاض العذارى", "taqdim": 0, "n_athar": 5, "qailun": [["عبد الله بن مسعود", "صحابي"], ["ابن عباس", "صحابي"], ["سعيد بن المسيب", "تابعي"]], "athar": [64797, 64798, 64801, 64802, 64814]}, {"n": 2, "t": "بل عنى بذلك أنهم في نعمة", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [64804, 64815]}, {"n": 3, "t": "بل معنى ذلك أنهم فى شغل عما فيه أهل النار", "taqdim": 0, "n_athar": 2, "qailun": [["الحسن فى قول الله", "تابعي"], ["إسماعيل بن أبي خالد", "تابعي"]], "athar": [64806]}]}, "mawaqif": [{"taliq": 5441, "mi": 1, "aya": 55, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 257", "qawl": "العموم", "nass": "وقال مجاهد: معناه: نعيم قد شغلهم. وهذا هو القول الصحيح، وتعيين شيء دون شيء لا قياس له", "qawaid": [], "tabi": ""}], "mushid": {"i": 12, "imgs": ["036_012_1.png"], "pages": [431], "n": 2, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 5441, "masala": "معنى الشغل الذي وصف الله -جل ثناؤه- أصحاب الجنة أنهم فيه يوم القيامة", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه افتضاض العذارى", "ashab": "", "athar": []}, {"n": 2, "t": "أنه النعمة", "ashab": "", "athar": []}, {"n": 3, "t": "أنهم في شغل عما فيه أهل النار", "ashab": "", "athar": []}, {"n": 4, "t": "أنه السماع", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن عطية", "رجّح العموم"]], "rules": {}, "rulesD": {}}}, {"aya": 55, "title": "في تأويل ذلك ﴿إن أصحاب الجنة اليوم في شغل فاكهون﴾", "tabari": {"page": "19/463", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه: فرحون", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [64798, 64801, 64814]}, {"n": 2, "t": "معناه: عجبون", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [64804, 64815]}, {"n": 3, "t": "ذلك بمنزلة: حاذرون وحذرون", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5442, "mi": 0, "aya": 55, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 463", "qawl": "", "nass": "والصواب من القراءة في ذلك عندي قراءة من قرأه بالألف؛ لأن ذلك هو القراءة المعروفة", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 5442, "mi": 0, "aya": 55, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 258", "qawl": "", "nass": "وقرأ جمهور الناس: {فاكهون}، معناه: أصحاب فاكهة، كما يقال: تامر، ولابن، وشاحم، ولاحم", "qawaid": [], "tabi": ""}, {"taliq": 5443, "mi": 0, "aya": 56, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 464", "qawl": "", "nass": "قرأه بعضهم: «في ظلل", "qawaid": [], "tabi": ""}, {"taliq": 5443, "mi": 0, "aya": 56, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "وقرأه آخرون: {في ظلال}؛ وإذا قرئ ذلك كذلك كان له وجهان: أحدهما: أن يكون مرادا به جمع الظل الذي هو بمعنى الكن، فيكون معنى الكلمة حينئذ: هم وأزواجهم في كن لا يضحون لشمس كما يضحي لها أهل الدنيا؛ لأنه لا شمس فيها. والآخر: أن يكون مرادا به: جمع ظلة، فيكون وجه جمعها كذلك نظير جمعهم الخلة في الكثرة: الخلال، والقلة: القلال", "qawaid": [], "tabi": ""}], "mushid": {"i": 13, "imgs": ["036_013_1.png"], "pages": [431], "n": 2, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["القراءة ورسم المصحف"]}, "rulesD": {}}}, {"aya": 66, "title": "في تأويل قوله: ﴿ولو نشاء لطمسنا على أعينهم فاستبقوا الصراط﴾", "tabari": {"page": "19/474", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى بذلك: ولو نشاء لأعميناهم عن الهدى، وأضللناهم عن قصد الحجة", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": []}, {"n": 2, "t": "معني ذلك: ولو نشاء لتركناهم عميا", "taqdim": 0, "n_athar": 2, "qailun": [["الحسن", "تابعي"], ["قتادة", "تابعي"]], "athar": []}]}, "mawaqif": [{"taliq": 5450, "mi": 1, "aya": 67, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 475", "qawl": "الثاني", "nass": "وهذا القول الذي ذكرناه عن الحسن وقتادة أشبه بتأويل الكلام؛ لأن الله إنما تهدد به قوما كفارا، فلا وجه لأن يقال وهم كفار: لو نشاء لأضللناهم. وقد أضلهم، ولكنه قال: لو نشاء لعاقبناهم على كفرهم، فطمسنا على أعينهم، فصيرناهم عميا لا يبصرون طريقا، ولا يهتدون له. والطمس على العين: هو أن لا يكون بين جفني العين غر، وذلك هو الشق الذي بين الجفنين، كما تطمس الريح الأثر، يقال: أعمى مطموس وطميس", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 14, "imgs": ["036_014_1.png"], "pages": [431], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5450, "masala": "تفسير قوله: {ولو نشاء لطمسنا أعينهم … } الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن معنى ذلك: ولو نشاء لأعميناهم عن الهدى، وأضللناهم عن قصد المحجة. وهو مروي عن ابن عباس، وعطاء، ومقاتل", "ashab": "", "athar": []}, {"n": 2, "t": "أن معنى ذلك: ولو نشاء لتركناهم عميا. وهو مروي عن الحسن، وقتادة", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 67, "title": "تأويل: ﴿ولو نشاء لمسخناهم على مكانتهم﴾", "tabari": {"page": "19/477", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿ولو نشاء لمسخناهم على مكانتهم﴾. يقول تعالى ذكره: ولو نشاء لأقعدنا هؤلاء المشركين من أرجلهم في منازلهم، ﴿فما استطاعوا مضيا ولا يرجعون﴾. يقول: فلا يستطيعون أن يمضوا أمامهم، ولا أن يرجعوا وراءهم.", "taqdim": 1, "n_athar": 2, "qailun": [["الحسن", "تابعي"], ["قتادة", "تابعي"]], "athar": [64897, 64900, 64901, 64905, 64911, 64913, 64915, 64917, 64919]}, {"n": 2, "t": "بل معنى ذلك: ولو نشاء لأهلكناهم في منازلهم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [64895, 64896, 64908, 64909, 64916]}]}, "mawaqif": [{"taliq": 5452, "mi": 1, "aya": 67, "alam": "ابن جرير", "fil": "اختار", "kind": "ترجيح", "ref": "19/ 477", "qawl": "الأول", "nass": "", "qawaid": ["أقوال السلف"], "tabi": ""}], "mushid": {"i": 15, "imgs": ["036_015_1.png"], "pages": [432], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5452, "masala": "تفسير قوله: {ولو نشاء لمسخناهم على مكانتهم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن معناه: ولو نشاء لأقعدناهم في منازلهم؛ فلا يستطيعون أن يمضوا أمامهم، ولا أن يرجعوا وراءهم", "ashab": "", "athar": []}, {"n": 2, "t": "أن معناه: ولو نشاء لأهلكناهم في منازلهم", "ashab": "", "athar": []}, {"n": 3, "t": "أن معناه: ولو نشاء لجعلناهم حجارة", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["أقوال السلف"]}, "rulesD": {}}}, {"aya": 69, "title": "عود الضمير من قوله: {وما ينبغي له}", "mawsua": {"taliq": 5453, "masala": "عود الضمير من قوله: {وما ينبغي له}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يعود على محمد", "ashab": "", "athar": []}, {"n": 2, "t": "أن يعود على القرآن، وإن كان لم يذكر لدلالة المجاورة عليه، ويبين ذلك قوله تعالى: {إن هو}", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5453, "mi": 1, "aya": 69, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 264", "qawl": "", "nass": "والضمير في {له} يحتمل أن يعود على محمد، ويحتمل أن يعود على القرآن، وإن كان لم يذكر لدلالة المجاورة عليه، ويبين ذلك قوله تعالى: {إن هو}", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 75, "title": "تأويل: ﴿وهم لهم جند محضرون﴾", "tabari": {"page": "19/484", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وهم لهم جند محضرون﴾. يقول: وهؤلاء المشركون لآلهتهم جند محضرون.", "taqdim": 1, "n_athar": 1, "qailun": [["مجاهد فى", "تابعي"]], "athar": []}, {"n": 2, "t": "بل معنى ذلك: وهم لهم جند محضرون فى الدنيا يغضبون لهم", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [64983, 64990]}]}, "mawaqif": [{"taliq": 5456, "mi": 1, "aya": 75, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 485", "qawl": "الثاني", "nass": "لأن المشركين عند الحساب تتبرأ منهم الأصنام، وما كانوا يعبدونه، فكيف يكونون لها جندا حينئذ، ولكنهم في الدنيا لهم جند يغضبون لهم، ويقاتلون دونهم", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5456, "mi": 1, "aya": 75, "alam": "ابن كثير", "fil": "ووافقه", "kind": "موافقة", "ref": "11/ 383", "qawl": "", "nass": "وهذا القول حسن", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5456, "mi": 1, "aya": 75, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 266", "qawl": "الأول", "nass": "على معنى التوبيخ والنقمة، وسماهم جندا في هذا التأويل إذ هم عدة للنقمة منهم وتوبيخهم", "qawaid": [], "tabi": ""}], "mushid": {"i": 16, "imgs": ["036_016_1.png", "036_016_2.png"], "pages": [432], "n": 4, "rajih": [4], "daif": [], "match": false}, "mawsua": {"taliq": 5456, "masala": "تفسير قوله: {وهم لهم جند مجضرون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن المعنى: وهم لهم جند محضرون يوم الحساب", "ashab": "", "athar": []}, {"n": 2, "t": "أن المعنى: وهم لهم جند محضرون في الدنيا، يغضبون لهم ويدافعون عنهم", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"], ["ابن كثير", "r"]], "1": [["ابن عطية", "w"]]}, "t": {"2": [["ابن جرير", "r"], ["ابن كثير", "r"]], "1": [["ابن عطية", "w"]]}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 79, "title": "تأويل: ﴿وضرب لنا مثلا﴾", "tabari": {"page": "19/486", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وضرب لنا مثلا﴾. قال: أبى بن خلف .", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "بل عنى به العاص بن وائل السهمى", "taqdim": 0, "n_athar": 1, "qailun": [["سعيد بن جبير", "تابعي"]], "athar": []}, {"n": 3, "t": "بل عنى به عبد الله بن أبى", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [65018]}]}, "mawaqif": [], "mushid": {"i": 17, "imgs": ["036_017_1.png"], "pages": [432], "n": 3, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [{"i": 8, "aya": 38, "imgs": ["036_008_1.png"], "pages": [430], "ihala": 0}, {"i": 10, "aya": 42, "imgs": ["036_010_1.png"], "pages": [431], "ihala": 0}], "others": {"1": [{"id": 5391, "kinds": "غيره", "text": "قال ابنُ القيم (2/ 356): «الصحيح أن {يس} بمنزلة {حم} و {ألم}، وليست اسمًا من أسماء النبي صلى الله عليه وسلم».", "mawaqif": [{"taliq": 5391, "mi": 0, "aya": 1, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "2/ 356", "qawl": "", "nass": "الصحيح أن {يس} بمنزلة {حم} و {ألم}، وليست اسما من أسماء النبي صلى الله عليه وسلم", "qawaid": [], "tabi": ""}]}], "2": [{"id": 5392, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 233): «و {الحَكِيمِ}: المحكم، فيكون بمعنى مفعول، أي: أُحكم في مواعظه وأوامره ونواهيه، ويحتمل أن يكون {الحَكِيمِ} بناء فاعل، أي: ذو الحكمة».", "mawaqif": [{"taliq": 5392, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 233", "qawl": "", "nass": "و {الحكيم}: المحكم، فيكون بمعنى مفعول، أي: أحكم في مواعظه وأوامره ونواهيه، ويحتمل أن يكون {الحكيم} بناء فاعل، أي: ذو الحكمة", "qawaid": [], "tabi": ""}]}], "4": [{"id": 5393, "kinds": "غيره", "text": "قال ابنُ جرير (19/ 400): «وفي قوله: {على صراط مستقيم} وجهان: أحدهما: أن يكون معناه: إنك لمن المرسلين على استقامة من الحق. فيكون حينئذ {على} من قوله: {على صراط مستقيم} من صلة الإرسال. والآخر: أن يكون خبرًا مبتدأ، كأنه قيل: إنك لمن المرسلين، إنك على صراط مستقيم».", "mawaqif": [{"taliq": 5393, "mi": 0, "aya": 4, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "19/ 400", "qawl": "", "nass": "وفي قوله: {على صراط مستقيم} وجهان: أحدهما: أن يكون معناه: إنك لمن المرسلين على استقامة من الحق. فيكون حينئذ {على} من قوله: {على صراط مستقيم} من صلة الإرسال. والآخر: أن يكون خبرا مبتدأ، كأنه قيل: إنك لمن المرسلين، إنك على صراط مستقيم", "qawaid": [], "tabi": ""}]}], "6": [{"id": 5394, "kinds": "تعليق", "text": "علّق ابنُ عطية (7/ 234) على قول عكرمة، فقال: «قال عكرمة: {ما} بمعنى: الذي، والتقدير: الشيء الذي أُنذره الآباء مِن النار والعذاب. ويحتمل أن تكون {ما} مصدرية، أي: ما أنذر آباءهم [إنذار آبائهم]. فـ» الآباء «على هذا كله هم الأقدمون على مر الدهر، وقوله تعالى: {فَهُمْ} مع هذا التأويل بمعنى: فإنهم، دخلت الفاء لقطع الجملة من الجملة».", "mawaqif": [{"taliq": 5394, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 234", "qawl": "عكرمة", "nass": "قال عكرمة: {ما} بمعنى: الذي، والتقدير: الشيء الذي أنذره الآباء من النار والعذاب. ويحتمل أن تكون {ما} مصدرية، أي: ما أنذر آباءهم [إنذار آبائهم]. ف", "qawaid": [], "tabi": ""}]}, {"id": 5395, "kinds": "بيان،تعليق", "text": "علّق ابنُ عطية (7/ 234) على قول قتادة، فقال: «وقال قتادة: {ما} نافية، أي: أن آباءهم لم ينذَروا، فالآباء على هذا هم القريبون منهم، وهذه الآية كقوله تعالى: {وما أرْسَلْنا إلَيْهِمْ قَبْلَكَ مِن نَذِيرٍ} [سبأ: 44]، وهذه النذارةُ المنفيةُ هي نذارة المباشرة والأمر والنهي، وإلا فدعوةُ الله تعالى مِن الأرض لم تنقطع قط، وقوله: {فَهُمْ} على هذا الفاء منه واصلة بين الجملتين، ورابطة للثانية بالأولى».", "mawaqif": [{"taliq": 5395, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 234", "qawl": "قتادة", "nass": "وقال قتادة: {ما} نافية، أي: أن آباءهم لم ينذروا، فالآباء على هذا هم القريبون منهم، وهذه الآية كقوله تعالى: {وما أرسلنا إليهم قبلك من نذير} [سبأ: 44]، وهذه النذارة المنفية هي نذارة المباشرة والأمر والنهي، وإلا فدعوة الله تعالى من الأرض لم تنقطع قط، وقوله: {فهم} على هذا الفاء منه واصلة بين الجملتين، ورابطة للثانية بالأولى", "qawaid": [], "tabi": ""}]}], "8": [{"id": 5396, "kinds": "ترجيح،نقل،حصر", "text": "لم يذكر ابنُ جرير (19/ 406) غير هذا الأثر.\nوذكره ابنُ عطية (7/ 235)، ثم ذكر قولًا آخر، فقال: «وقالت فرقة: الآيةُ مُستعارة المعاني مِن منع الله تعالى آباءهم من الإيمان، وحوْلِه بينهم وبينه». ورجّحه مستندًا إلى السياق بقوله: «وهذا أرجح الأقوال؛ لأنه تعالى لما ذكر أنهم لا يؤمنون بما سبق لهم في الأزل؛ عَقَّب ذلك بأن جعل لهم مِن المنع وإحاطة الشقاوة ما حالهم معه حال المغللين. والغُلّ: ما أحاط بالعُنق على معنى التَّضْييق والتثبيت والتعذيب والأسْر، ومع العنق اليدان أو اليد الواحدة، هذا معنى التغليل».", "mawaqif": [{"taliq": 5396, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "7/ 235", "qawl": "", "nass": "وقالت فرقة: الآية مستعارة المعاني من منع الله تعالى آباءهم من الإيمان، وحوله بينهم وبينه", "qawaid": ["السياق"], "tabi": ""}]}, {"id": 5397, "kinds": "خلاف،ترجيح،توجيه،نقل", "text": "ذكر ابنُ عطية (7/ 235) في قوله: {فهي} قولين، فقال: «وقوله تعالى: {فَهِيَ} يحتمل أن يعود على الأغلال، أي: هي عريضة تبلغ بحرفها الأذقان، والذقن: مجتمع اللحيين، فيضطر المغلول إلى رفع وجهه نحو السماء، وذلك هو الإقماح، وهو نحو الإقناع في الهيئة، ونحوه ما يفعله الإنسان والحيوان عند شرب الماء البارد، وعند الملوحات والحموضة القوية ونحوه. ويحتمل-وهو قول الطبري- أن تعود» هي «على الأيدي، وإن لم يتقدم لها ذكر؛ لوضوح مكانها من المعنى، وذلك أن الغل إنما يكون في العنق مع اليدين».\nوذكر ابنُ القيم (2/ 357) هذين القولين، ثم رجّح عود الضمير على الأغلال بقوله: «وهذا هو الظاهر». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 5397, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 235", "qawl": "", "nass": "وقوله تعالى: {فهي} يحتمل أن يعود على الأغلال، أي: هي عريضة تبلغ بحرفها الأذقان، والذقن: مجتمع اللحيين، فيضطر المغلول إلى رفع وجهه نحو السماء، وذلك هو الإقماح، وهو نحو الإقناع في الهيئة، ونحوه ما يفعله الإنسان والحيوان عند شرب الماء البارد، وعند الملوحات والحموضة القوية ونحوه. ويحتمل-وهو قول الطبري- أن تعود", "qawaid": [], "tabi": ""}, {"taliq": 5397, "mi": 0, "aya": 8, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 357", "qawl": "", "nass": "وهذا هو الظاهر", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 5398, "kinds": "حصر", "text": "لم يذكر ابن جرير (19/ 404) غير قول مجاهد.", "mawaqif": []}, {"id": 5399, "kinds": "ترجيح،نقد،بيان،نقل", "text": "نقل ابنُ عطية (7/ 235) عن مكيٍّ في هذه الآية قولَه: «هذه حقيقة في أحوال الآخرة إذا دخلوا النار». ثم انتقده مستندًا إلى السياق، فقال: «وقوله تعالى: {فأغشيناهم فهم لا يبصرون} يُضعِف هذا القول؛ لأنّ بصر الكافر يوم القيامة إنما هو حديدٌ يرى قبح حاله». ثم ذكر عن فرقة أنها قالت: «الآيةُ مستعارة المعنى مِن منع الله إيّاهم وحَوْلِه بينه وبينهم». ورجّحه مستندًا إلى السياق، فقال: «وهذا أرجح الأقوال؛ لأنه تعالى لما ذكر أنهم لا يؤمنون بما سبق لهم في الأزل عَقَّب ذلك بأن جعل لهم من المنع وإحاطة الشقاوة ما حالهم معه حال المغللين».", "mawaqif": [{"taliq": 5399, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 235", "qawl": "", "nass": "هذه حقيقة في أحوال الآخرة إذا دخلوا النار", "qawaid": ["السياق"], "tabi": ""}]}], "9": [{"id": 5400, "kinds": "ترجيح", "text": "رجّح ابنُ جرير (19/ 405) قراءة الضم في «سُدًّا» مع بيان صحة وجواز قراءة النصب فيها، فقال: «والضم أعجب القراءتين إلَيَّ في ذلك، وإن كانت الأخرى جائزةً صحيحة». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 5400, "mi": 0, "aya": 9, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 405", "qawl": "", "nass": "سدا", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 5401, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 236) قول عكرمة، ثم علّق بقوله: «والسد: ما سد وحال، ومنه قول الأعرابي في صفة سحاب: طلعَ سُدٌّ مع انتشار الطِّفْل، أي: سحاب سدَّ الأفق، ومنه قولهم: جراد سد، ومعنى الآية: أن طريق الهدى سُدَّ دونهم».", "mawaqif": [{"taliq": 5401, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 236", "qawl": "عكرمة", "nass": "والسد: ما سد وحال، ومنه قول الأعرابي في صفة سحاب: طلع سد مع انتشار الطفل، أي: سحاب سد الأفق، ومنه قولهم: جراد سد، ومعنى الآية: أن طريق الهدى سد دونهم", "qawaid": [], "tabi": ""}]}, {"id": 5402, "kinds": "نقل", "text": "قال ابنُ جرير (19/ 407): «وقد روي عن ابن عباس أنه كان يقرأ ذلك: (فَأَعْشَيْناهُمْ فَهُمْ لا يُبْصِرُونَ) بالعين، بمعنى: أعشيناهم عنه، وذلك أنّ العشا بالليل، وهو أن يمشي بالليل ولا يبصر».\nوبنحوه ابنُ عطية (7/ 236 - 237).", "mawaqif": [{"taliq": 5402, "mi": 0, "aya": 9, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "19/ 407", "qawl": "", "nass": "وقد روي عن ابن عباس أنه كان يقرأ ذلك: (فأعشيناهم فهم لا يبصرون) بالعين، بمعنى: أعشيناهم عنه، وذلك أن العشا بالليل، وهو أن يمشي بالليل ولا يبصر", "qawaid": [], "tabi": ""}, {"taliq": 5402, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "7/ 236 - 237", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}]}], "12": [{"id": 5403, "kinds": "نقد،توجيه،تعليق،نقل،استدلال", "text": "ظاهر هذا الأثر يُوحِي بنزول هذه الآية بالمدينة، ولهذا علّق ابنُ كثير (11/ 349) على هذا الأثر بقوله: «وفيه غرابة من حيث ذكر نزول هذه الآية، والسورة بكمالها مكية».\nوانتقد ابنُ عطية (7/ 231) ذلك بقوله: «وليس الأمر كذلك». ثم وجّه التعبير بالنزول في هذه الآية بقوله: «وإنما نزلت الآية بمكة، ولكنه احتجَّ بها عليهم في المدينة، ووافقها قول النبي صلى الله عليه وسلم في المعنى، فمِن هنا قال مَن قال: إنها نزلت في بني سلمة».\nوذكر ابنُ القيم (2/ 359) هذا الأثر في مستندات مَن قال بنزول الآية في بني سلمة، ثم انتقده مستندًا لأحوال النزول بقوله: «وفي هذا القول نظر؛ فإن سورة يس مكية، وقصة بني سلمة بالمدينة، إلا أن يقال: هذه الآية وحدها مدنية، وأحسن مِن هذا أن تكون ذكرت عند هذه القصة، ودلَّت عليها، وذُكِّروا بها عندها؛ إمّا من النبي صلى الله عليه وسلم، وإما من جبريل، فأطلق على ذلك النزول، ولعل هذا مراد مَن قال في نظائر ذلك: نزلت مرتين».", "mawaqif": [{"taliq": 5403, "mi": 0, "aya": 12, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 349", "qawl": "", "nass": "وفيه غرابة من حيث ذكر نزول هذه الآية، والسورة بكمالها مكية", "qawaid": [], "tabi": ""}, {"taliq": 5403, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 231", "qawl": "", "nass": "وليس الأمر كذلك", "qawaid": [], "tabi": ""}, {"taliq": 5403, "mi": 0, "aya": 12, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 359", "qawl": "", "nass": "وفي هذا القول نظر؛ فإن سورة يس مكية، وقصة بني سلمة بالمدينة، إلا أن يقال: هذه الآية وحدها مدنية، وأحسن من هذا أن تكون ذكرت عند هذه القصة، ودلت عليها، وذكروا بها عندها؛ إما من النبي صلى الله عليه وسلم، وإما من جبريل، فأطلق على ذلك النزول، ولعل هذا مراد من قال في نظائر ذلك: نزلت مرتين", "qawaid": ["سبب النزول وأحواله"], "tabi": ""}]}, {"id": 5404, "kinds": "نقد،بيان،تعليق،نقل", "text": "ذكر ابنُ القيم (2/ 358 - 359) قول مقاتل، وعلّق عليه بقوله: «وكأنّ مقاتلًا أراد التمثيل والبيان، على عادة السلف في تفسير اللفظة العامة بنوعٍ أو فردٍ مِن أفراد مدلولها، تقريبًا وتمثيلًا، لا حصرًا وإحاطة». وذكر ابنُ القيم قولًا عن ابن عباس أنه قال: آثارهم: ما أثروا من خير أو شر، كقوله: {ينبأ الإنسان يومئذ بما قدم وأخر} [القيامة: 13]. وبيّن أن هذا القول أعمُّ من قول مقاتل.", "mawaqif": [{"taliq": 5404, "mi": 0, "aya": 12, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 358 - 359", "qawl": "مقاتل", "nass": "وكأن مقاتلا أراد التمثيل والبيان، على عادة السلف في تفسير اللفظة العامة بنوع أو فرد من أفراد مدلولها، تقريبا وتمثيلا، لا حصرا وإحاطة", "qawaid": [], "tabi": ""}, {"taliq": 5404, "mi": 0, "aya": 12, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "أعم من", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 5405, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (19/ 408 - 409) في قوله: {ونكتب ما قدموا} غير قول ابن زيد وقتادة ومجاهد.", "mawaqif": []}, {"id": 5407, "kinds": "نقل", "text": "قال ابنُ عطية (7/ 238): «والإمام: الكتاب المقتدى به، الذي هو حجة». ثم ذكر ما جاء في أقوال السلف أنه اللوح المحفوظ، ثم ذكر عن فرقة أنها قالت: هو صحف الأعمال.", "mawaqif": [{"taliq": 5407, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 238", "qawl": "", "nass": "والإمام: الكتاب المقتدى به، الذي هو حجة", "qawaid": [], "tabi": ""}]}], "13": [{"id": 5408, "kinds": "تعليق،نقل", "text": "علّق ابنُ عطية (7/ 242) على قول كعب، فقال: «وذكر الناسُ مِن أسماء الرسل: صادق، وصدوق، وشلوم، وغير هذا، والصحة معدومة؛ فاختصرته».", "mawaqif": [{"taliq": 5408, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 242", "qawl": "كعب", "nass": "وذكر الناس من أسماء الرسل: صادق، وصدوق، وشلوم، وغير هذا، والصحة معدومة؛ فاختصرته", "qawaid": [], "tabi": ""}]}], "18": [{"id": 5411, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (7/ 240) في السبب الذي من أجله قالوا: {إنا تطيرنا بكم} ما جاء في قول مقاتل، وذكر قولًا آخر أنهم قالوا ذلك لأن الجذام انتشر فيهم، ثم رجَّح مستندًا إلى النظائرأن تطيرهم: «إنما كان بسبب ما دخل قريتهم من اختلاف الكلمة وافتتان الناس، وهذا على نحو تطير قريش بمحمد صلى الله عليه وسلم، وعلى نحو ما خُوطِب به موسى».", "mawaqif": [{"taliq": 5411, "mi": 0, "aya": 18, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 240", "qawl": "مقاتل", "nass": "إنما كان بسبب ما دخل قريتهم من اختلاف الكلمة وافتتان الناس، وهذا على نحو تطير قريش بمحمد صلى الله عليه وسلم، وعلى نحو ما خوطب به موسى", "qawaid": ["القرآن والنظائر"], "tabi": ""}]}, {"id": 5412, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (19/ 416) غير قول قتادة.", "mawaqif": []}], "19": [{"id": 5413, "kinds": "توجيه،بيان،نقل", "text": "ذكر ابنُ عطية (7/ 240) ما جاء في هذا القول، وقال: «وبهذا فسر الناس». ثم وجّهه بقوله: «وسمي الحظ والنصيب طائرًا استعارة، أي: هو مما يحصل عن النظر في الطائر، وكثر استعمال هذا المعنى حتى قالت المرأة الأنصارية: فطار لنا. حين اقتسم المهاجرون عثمان بن مظعون، ويقول الفقهاء: طار لفلان في المحاصَّة كذا».", "mawaqif": [{"taliq": 5413, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 240", "qawl": "", "nass": "وبهذا فسر الناس", "qawaid": [], "tabi": ""}]}, {"id": 5414, "kinds": "ترجيح،تعليق", "text": "علّق ابنُ جرير (19/ 417 - 418) على هذه القراءة، فقال: «قرأته عامة قراء الأمصار: {أئن ذكرتم} بكسر الألف من» إن «وفتح ألف الاستفهام، بمعنى: إن ذكرناكم فمعكم طائركم. ثم أدخل على» إن «-التي هي حرف جزاء- ألف استفهام في قول بعض نحويي البصرة، وفي قول بعض الكوفيين منوي به التكرير، كأنه قيل: قالوا: طائركم معكم إن ذكرتم فمعكم طائركم، فحذف الجواب اكتفاء بدلالة الكلام عليه».\nوعلّق عليها ابنُ عطية قائلًا (7/ 241 بتصرف): «وقُرِئ {أئن} بهمزتين الثانية مكسورة، على معنى: أئن ذكرتم تتطيرون».\nثم رجّحها ابنُ جرير مستندًا إلى إجماع الحجة من القراء، وأقوال السلف، فقال: «والقراءة التي لا نجيز القراءة بغيرها القراءة التي عليها قراء الأمصار، وهي دخول ألف الاستفهام على حرف الجزاء، وتشديد الكاف على المعنى الذي ذكرناه عن قارئيه كذلك، لإجماع الجحة من القراء عليه وبنحو الذي قلنا في ذلك قال أهل التأويل».", "mawaqif": [{"taliq": 5414, "mi": 0, "aya": 19, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "19/ 417 - 418", "qawl": "", "nass": "قرأته عامة قراء الأمصار: {أئن ذكرتم} بكسر الألف من", "qawaid": [], "tabi": ""}, {"taliq": 5414, "mi": 0, "aya": 19, "alam": "ابن جرير", "fil": "رجحها", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "والقراءة التي لا نجيز القراءة بغيرها القراءة التي عليها قراء الأمصار، وهي دخول ألف الاستفهام على حرف الجزاء، وتشديد الكاف على المعنى الذي ذكرناه عن قارئيه كذلك، لإجماع الجحة من القراء عليه وبنحو الذي قلنا في ذلك قال أهل التأويل", "qawaid": ["القراءة ورسم المصحف", "أقوال السلف"], "tabi": ""}]}, {"id": 5415, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (19/ 418) غير قول قتادة.", "mawaqif": []}], "20": [{"id": 5416, "kinds": "نقد،نقل", "text": "انتقد ابنُ كثير (11/ 257 - 258 بتصرف) مستندًا إلى ظاهر القرآن، ودلالة التاريخ، والدلالة العقلية كون المدينة أنطاكية، فقال: «وقد تقدم عن كثير من السلف أن هذه القرية هي أنطاكية … وفي ذلك نظر من وجوه: أحدها: أن أهل أنطاكية آمنوا برسل المسيح إليهم، وكانوا أول مدينة آمنت بالمسيح؛ ولهذا كانت عند النصارى إحدى المدائن الأربعة اللاتي فيهن بَتاركة، وهن: القدس؛ لأنها بلد المسيح، وأنطاكية؛ لأنها أول بلدة آمنت بالمسيح عن آخر أهلها، والإسكندرية؛ لأن فيها اصطلحوا على اتخاذ البتاركة والمطارنة والأساقفة والقساوسة والشمامسة والرهابين، ثم رومية؛ لأنها مدينة الملك قسطنطين الذي نصر دينهم وأطده. ولما ابتنى القسطنطينية نقلوا البترك من رومية إليها، كما ذكره غير واحد ممن ذكر تواريخهم، كسعيد بن بطريق وغيره من أهل الكتاب والمسلمين، فإذا تقرر أن أنطاكية أول مدينة آمنت فأهل هذه القرية قد ذكر الله تعالى أنهم كذبوا رسله، وأنه أهلكهم بصيحة واحدة أخمدتهم، فالله أعلم. الثاني: أن قصة أنطاكية مع الحواريين أصحاب المسيح بعد نزول التوراة، وقد ذكر أبو سعيد الخدري وغير واحد من السلف: أن الله تعالى بعد إنزاله التوراة لم يهلك أمةً مِن الأمم عن آخرهم بعذاب يبعثه عليهم، بل أمر المؤمنين بعد ذلك بقتال المشركين. ذكروه عند قوله تعالى: {ولقد آتينا موسى الكتاب من بعد ما أهلكنا القرون الأولى} [القصص: 43]. فعلى هذا يتعيَّن أن هذه القرية المذكورة في القرآن العظيم قرية أخرى غير أنطاكية، كما أطلق ذلك غير واحد من السلف أيضًا. أو تكون أنطاكية إن كان لفظها محفوظًا في هذه القصة مدينة أخرى غير هذه المشهورة المعروفة، فإن هذه لم يعرف أنها أهلكت لا في الملة النصرانية ولا قبل ذلك».\nوبنحوه ابنُ تيمية (5/ 318 - 323) في كلام طويل.", "mawaqif": [{"taliq": 5416, "mi": 0, "aya": 20, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "11/ 257 - 258 بتصرف", "qawl": "", "nass": "وقد تقدم عن كثير من السلف أن هذه القرية هي أنطاكية … وفي ذلك نظر من وجوه: أحدها: أن أهل أنطاكية آمنوا برسل المسيح إليهم، وكانوا أول مدينة آمنت بالمسيح؛ ولهذا كانت عند النصارى إحدى المدائن الأربعة اللاتي فيهن بتاركة، وهن: القدس؛ لأنها بلد المسيح، وأنطاكية؛ لأنها أول بلدة آمنت بالمسيح عن آخر أهلها، والإسكندرية؛ لأن فيها اصطلحوا على اتخاذ البتاركة والمطارنة والأساقفة والقساوسة والشمامسة والرهابين، ثم رومية؛ لأنها مدينة الملك قسطنطين الذي نصر دينهم وأطده. ولما ابتنى القسطنطينية نقلوا البترك من رومية إليها، كما ذكره غير واحد ممن ذكر تواريخهم، كسعيد بن بطريق وغيره من أهل الكتاب والمسلمين، فإذا تقرر أن أنطاكية أول مدينة آمنت فأهل هذه القرية قد ذكر الله تعالى أنهم كذبوا رسله، وأنه أهلكهم بصيحة واحدة أخمدتهم، فالله أعلم. الثاني: أن قصة أنطاكية مع الحواريين أصحاب المسيح بعد نزول التوراة، وقد ذكر أبو سعيد الخدري وغير واحد من السلف: أن الله تعالى بعد إنزاله التوراة لم يهلك أمة من الأمم عن آخرهم بعذا", "qawaid": ["ظاهر الآية ولفظها", "التاريخ والواقع", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5416, "mi": 0, "aya": 20, "alam": "ابن تيمية", "fil": "وبنحوه", "kind": "موافقة", "ref": "5/ 318 - 323", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن كثير"}]}], "25": [{"id": 5417, "kinds": "تعليق", "text": "علّق ابنُ عطية (7/ 243) على ما جاء في هذا القول، فقال: «قال ابن عباس وكعب ووهب: خاطب بها قومَه. على جهة المبالغة والتنبيه».", "mawaqif": [{"taliq": 5417, "mi": 0, "aya": 25, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 243", "qawl": "", "nass": "قال ابن عباس وكعب ووهب: خاطب بها قومه. على جهة المبالغة والتنبيه", "qawaid": [], "tabi": ""}]}], "29": [{"id": 5421, "kinds": "تعليق", "text": "علّق ابنُ عطية (7/ 245) على قراءة ابن مسعود، فقال: «وقرأ ابن مسعود، وعبد الرحمن بن الأسود: (إلّا زَقْيَةً)، وهي: الصيحة من الديك ونحوه مِن الطير».", "mawaqif": [{"taliq": 5421, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 245", "qawl": "", "nass": "وقرأ ابن مسعود، وعبد الرحمن بن الأسود: (إلا زقية)، وهي: الصيحة من الديك ونحوه من الطير", "qawaid": [], "tabi": ""}]}], "30": [{"id": 5422, "kinds": "تعليق", "text": "علّق ابنُ عطية (7/ 246 بتصرف) على قراءة ابن عباس، فقال: «وقرأ ابن عباس (يا حَسْرَةَ العِبادِ) بإضافتها، وقول ابن عباس حسنٌ مع قراءته». يريد تفسيره الآتي: يا ويلًا للعباد.", "mawaqif": [{"taliq": 5422, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 246 بتصرف", "qawl": "", "nass": "وقرأ ابن عباس (يا حسرة العباد) بإضافتها، وقول ابن عباس حسن مع قراءته", "qawaid": [], "tabi": ""}]}, {"id": 5423, "kinds": "نقل", "text": "ذكر ابنُ كثير (11/ 359) هذه القراءة، ثم قال معلّقًا: «ومعنى هذا: يا حسرتهم وندامتهم يوم القيامة إذا عاينوا العذاب، كيف كذبوا رسل الله، وخالفوا أمر الله، فإنهم كانوا في الدار الدنيا المكذبون منهم».", "mawaqif": [{"taliq": 5423, "mi": 0, "aya": 30, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 359", "qawl": "", "nass": "ومعنى هذا: يا حسرتهم وندامتهم يوم القيامة إذا عاينوا العذاب، كيف كذبوا رسل الله، وخالفوا أمر الله، فإنهم كانوا في الدار الدنيا المكذبون منهم", "qawaid": [], "tabi": ""}]}, {"id": 5424, "kinds": "نقد،توجيه", "text": "وجّه ابنُ عطية (7/ 246) قول أبي العالية، فقال: «وقال أبو العالية: المراد بـ {العِبادِ}: الرسل الثلاثة. فكأن هذا التحسر من الكفار حين رأوا عذاب الله تلهفوا على ما فاتهم». ثم انتقده مستندًا إلى السياق بقوله: «وقوله تعالى: {ما يَأْتِيهِمْ} الآية، يدافع هذا التأويل».", "mawaqif": [{"taliq": 5424, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 246", "qawl": "أبي العالية", "nass": "وقال أبو العالية: المراد ب {العباد}: الرسل الثلاثة. فكأن هذا التحسر من الكفار حين رأوا عذاب الله تلهفوا على ما فاتهم", "qawaid": ["السياق"], "tabi": ""}]}, {"id": 5425, "kinds": "نقد،نقل،حصر", "text": "لم يذكر ابنُ جرير (19/ 429 - 430) غير قول قتادة، وقول مجاهد، وقول ابن عباس من طريق علي.\nواستدرك ابنُ عطية (7/ 246 بتصرف) على ما ذهب إليه ابنُ جرير، فقال: «قال الطبري: المعنى: يا حسرة العباد على أنفسهم. وذكر أنها في بعض القراءات كذلك. وتأويل الطبري في ذلك القراءة الأولى ليس بالبين، وإنما يتجه أن يكون المعنى: تلهفًا على العباد، كأن الحال يقتضيه وطباع كل بشر توجب عند سماعه حالهم وعذابهم على الكفر وتضييعهم أمر الله تعالى أن يشفق ويتحسر على العباد».", "mawaqif": [{"taliq": 5425, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "استدرك", "kind": "نقد", "ref": "7/ 246 بتصرف", "qawl": "", "nass": "قال الطبري: المعنى: يا حسرة العباد على أنفسهم. وذكر أنها في بعض القراءات كذلك. وتأويل الطبري في ذلك القراءة الأولى ليس بالبين، وإنما يتجه أن يكون المعنى: تلهفا على العباد، كأن الحال يقتضيه وطباع كل بشر توجب عند سماعه حالهم وعذابهم على الكفر وتضييعهم أمر الله تعالى أن يشفق ويتحسر على العباد", "qawaid": [], "tabi": ""}]}], "32": [{"id": 5426, "kinds": "توجيه،تعليق", "text": "علّق ابنُ جرير (19/ 431) على هذه القراءة، فقال: \"وقرأ ذلك عامة قراء أهل الكوفة: {لما} بتشديد الميم. ولتشديدهم ذلك عندنا وجهان: أحدهما: أن يكون الكلام عندهم كان مرادًا به: وإن كل لمما جميع. ثم حذفت إحدى الميمات لما كثرت، كما قال الشاعر:\nغَداةَ طَفَتْ عَلْماءِ بكر بن وائل وعُجْنا صدور الخيلِ نحوَ تَمِيمِوالآخر: أن يكونوا أرادوا أن تكون {لما} بمعنى: إلا مع إن خاصة، فتكون نظيرة إنما إذا وضعت موضع إلا «. ثم علّق عليها وعلى قراءة التخفيف، فقال:» والصواب من القول في ذلك عندي أنهما قراءتان مشهورتان متقاربتا المعنى، فبأيتهما قرأ القارئ فمصيب\".\nووجّه ابنُ عطية (7/ 247) قراءة التخفيف، فقال: «وقرأ الجمهور «لَما» بتخفيف الميم، وذلك على زيادة» ما «للتأكيد، والمعنى: لَجميع».\nوعلّق ابن كثير (11/ 359) على القراءتين بقوله: «ومعنى القراءتين واحد».", "mawaqif": [{"taliq": 5426, "mi": 0, "aya": 32, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "19/ 431", "qawl": "", "nass": ". ثم علق عليها وعلى قراءة التخفيف، فقال:", "qawaid": [], "tabi": ""}, {"taliq": 5426, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 247", "qawl": "", "nass": "وقرأ الجمهور «لما", "qawaid": [], "tabi": ""}, {"taliq": 5426, "mi": 0, "aya": 32, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 359", "qawl": "", "nass": "ومعنى القراءتين واحد", "qawaid": [], "tabi": ""}]}], "35": [{"id": 5427, "kinds": "نقل", "text": "ذكر ابنُ جرير (19/ 433) في «ما» من قوله: {وما عملته أيديهم} ثلاثة أوجه، فقال: «و» ما «التي في قوله: «وما عَمِلَتْ أيْدِيهِمْ» [كذا، وهي قراءة حمزة والكسائي وأبي بكر عن عاصم] في موضع خفض عطفًا على الثمر، بمعنى: ومن الذي عملت أيديهم، وهي في قراءة عبد الله فيما ذكر: (ومِمّا عَمِلَتْهُ) بالهاء على هذا المعنى؛ فالهاء في قراءتنا مضمرة، لأن العرب تضمرها أحيانًا، وتظهرها في صلات: من، وما، والذي. ولو قيل:» ما «بمعنى المصدر كان مذهبًا، فيكون معنى الكلام: ومن عمل أيديهم. ولو قيل: إنها بمعنى الجحد، ولا موضع لها؛ كان أيضًا مذهبًا، فيكون معنى الكلام: ليأكلوا من ثمره، ولم تعمله أيديهم».\nوبنحوه ابنُ عطية (7/ 248).", "mawaqif": [{"taliq": 5427, "mi": 0, "aya": 35, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 433", "qawl": "", "nass": "ما", "qawaid": [], "tabi": ""}, {"taliq": 5427, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "7/ 248", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}]}], "37": [{"id": 5428, "kinds": "ترجيح،نقد،نقل", "text": "ذكر ابنُ جرير (19/ 434) أن معنى: {وآية لهم الليل نسلخ منه النهار} أي: ننزِع عنه النهار. ثم ذكر قول قتادة، وانتقده مستندًا إلى الدلالة العقلية قائلًا: «وهذا الذي قاله قتادة في ذلك عندي مِن معنى سلخ النهار من الليل بعيد؛ وذلك أن إيلاج الليل في النهار إنما هو زيادة ما نقص من ساعات هذا في ساعات الآخر، وليس السلخ من ذلك في شيء؛ لأن النهار يسلخ من الليل كله، وكذلك الليل من النهار كله، وليس يولج كل الليل في كل النهار، ولا كل النهار في كل الليل».\nووافقه ابنُ كثير (11/ 360). ورجّح ابنُ كثير مستندًا إلى ظاهر الآية أن المعنى: «{وآية لهم الليل نسلخ منه النهار} أي: نصرمه منه فيذهب، فيقبل الليل؛ ولهذا قال: {فإذا هم مظلمون} كما جاء في الحديث: «إذا أقبل الليل من هاهنا، وأدبر النهار من هاهنا، وغربت الشمس، فقد أفطر الصائم». هذا هو الظاهر من الآية».", "mawaqif": [{"taliq": 5428, "mi": 0, "aya": 37, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 434", "qawl": "قتادة", "nass": "وهذا الذي قاله قتادة في ذلك عندي من معنى سلخ النهار من الليل بعيد؛ وذلك أن إيلاج الليل في النهار إنما هو زيادة ما نقص من ساعات هذا في ساعات الآخر، وليس السلخ من ذلك في شيء؛ لأن النهار يسلخ من الليل كله، وكذلك الليل من النهار كله، وليس يولج كل الليل في كل النهار، ولا كل النهار في كل الليل", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5428, "mi": 0, "aya": 37, "alam": "ابن كثير", "fil": "ووافقه", "kind": "موافقة", "ref": "11/ 360", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5428, "mi": 0, "aya": 37, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "{وآية لهم الليل نسلخ منه النهار} أي: نصرمه منه فيذهب، فيقبل الليل؛ ولهذا قال: {فإذا هم مظلمون} كما جاء في الحديث: «إذا أقبل الليل من هاهنا، وأدبر النهار من هاهنا، وغربت الشمس، فقد أفطر الصائم", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}], "38": [{"id": 5429, "kinds": "نقل", "text": "ذكر ابنُ كثير (11/ 362) قراءة ابن عباس وابن مسعود، ثم وجّهها، فقال: «وقرأ ابن مسعود، وابن عباس: (والشَّمْسُ تَجْرِي لا مُسْتَقَرَّ لَها» أي: لا قرار لها ولا سكون، بل هي سائرة ليلًا ونهارًا، لا تفتر ولا تقف. كما قال تعالى: {وسخر لكم الشمس والقمر دائبين} [إبراهيم: 33]، أي: لا يفتران ولا يقفان إلى يوم القيامة\".", "mawaqif": [{"taliq": 5429, "mi": 0, "aya": 38, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 362", "qawl": "", "nass": "وقرأ ابن مسعود، وابن عباس: (والشمس تجري لا مستقر لها", "qawaid": [], "tabi": ""}]}], "39": [{"id": 5430, "kinds": "توجيه", "text": "وجّه ابنُ كثير (11/ 363) قول ابن عباس، فقال: «يعني ابن عباس: أصل العنقود مِن الرطب إذا عَتُق ويبس وانحنى».", "mawaqif": [{"taliq": 5430, "mi": 0, "aya": 39, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "11/ 363", "qawl": "ابن عباس", "nass": "يعني ابن عباس: أصل العنقود من الرطب إذا عتق ويبس وانحنى", "qawaid": [], "tabi": ""}]}, {"id": 5431, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 250) قول الحسن، ثم علّق عليه قائلًا: «العرجون: وهو الغصن من النخلة الذي فيه شماريخ التمر، فإنه ينحني ويصفر إذا قدم، ويجيء أشبه شيء بالهلال. قاله الحسن بن أبي الحسن، والوجود يشهد به».", "mawaqif": [{"taliq": 5431, "mi": 0, "aya": 39, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 250", "qawl": "الحسن", "nass": "العرجون: وهو الغصن من النخلة الذي فيه شماريخ التمر، فإنه ينحني ويصفر إذا قدم، ويجيء أشبه شيء بالهلال. قاله الحسن بن أبي الحسن، والوجود يشهد به", "qawaid": [], "tabi": ""}]}], "40": [{"id": 5432, "kinds": "بيان،تعليق،نقل", "text": "قال ابن جرير (19/ 438): «وقوله: {لا الشمس ينبغي لها أن تدرك القمر} يقول -تعالى ذِكْرُه-: لا الشمس يصلح لها إدراك القمر، فيذهب ضوءها بضوئه، فتكون الأوقات كلها نهارًا لا ليل فيها، {ولا الليل سابق النهار} يقول -تعالى ذكره-: ولا الليل بفائت النهار حتى تذهب ظلمته بضيائه، فتكون الأوقات كلها ليلًا. وبنحو الذي قلنا في ذلك قال أهل التأويل على اختلاف منهم في ألفاظهم في تأويل ذلك، إلا أن معاني عامتهم الذي قلناه». ثم ذكر قول ابن عباس من طريق عطية العوفي، ومجاهد بن جبر من طريق ابن أبي نجيح، وقتادة، وأبي صالح باذام، والضحاك بن مزاحم من طريق عبيد.\nوذكر ابنُ كثير (11/ 264) عبارات السلف في تفسير الآية، ثم علّق قائلًا: «والمعنى في هذا: أنّه لا فترة بين الليل والنهار، بل كل منهما يعقب الآخر بلا مهلة ولا تراخٍ؛ لأنهما مسخَّران دائبين يتطالبان طلبًا حثيثًا».", "mawaqif": [{"taliq": 5432, "mi": 0, "aya": 40, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "19/ 438", "qawl": "", "nass": "وقوله: {لا الشمس ينبغي لها أن تدرك القمر} يقول -تعالى ذكره-: لا الشمس يصلح لها إدراك القمر، فيذهب ضوءها بضوئه، فتكون الأوقات كلها نهارا لا ليل فيها، {ولا الليل سابق النهار} يقول -تعالى ذكره-: ولا الليل بفائت النهار حتى تذهب ظلمته بضيائه، فتكون الأوقات كلها ليلا. وبنحو الذي قلنا في ذلك قال أهل التأويل على اختلاف منهم في ألفاظهم في تأويل ذلك، إلا أن معاني عامتهم الذي قلناه", "qawaid": [], "tabi": ""}, {"taliq": 5432, "mi": 0, "aya": 40, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 264", "qawl": "", "nass": "والمعنى في هذا: أنه لا فترة بين الليل والنهار، بل كل منهما يعقب الآخر بلا مهلة ولا تراخ؛ لأنهما مسخران دائبين يتطالبان طلبا حثيثا", "qawaid": [], "tabi": ""}]}], "45": [{"id": 5434, "kinds": "ترجيح،نقد،توجيه،بيان،تعليق،نقل،استدلال", "text": "قال ابنُ جرير (19/ 447): «قوله تعالى: {وإذا قيل لهم اتقوا ما بين أيديكم وما خلفكم لعلكم ترحمون وما تأتيهم من آية من آيات ربهم إلا كانوا عنها معرضين} يقول -تعالى ذكره-: وإذا قيل لهؤلاء المشركين بالله، المكذبين رسوله محمدًا صلى الله عليه وسلم: احذروا ما مضى بين أيديكم مِن نقم الله ومثلاته بِمَن حلَّ ذلك به مِن الأمم قبلكم أن يحل مثله بكم، بشرككم وتكذيبكم رسوله {وما خلفكم} يقول: وما بعد هلاككم مما أنتم لاقوه إن هلكتم على كفركم الذي أنتم عليه». واستدل بقول قتادة.\nوذكر ابنُ جرير قول مجاهد، ثم وجّهه (19/ 449) بقوله: «وهذا القول قريب المعنى مِن القول الذي قلنا؛ لأن معناه: اتقوا عقوبة ما بين أيديكم من ذنوبكم، وما خلفكم مما تعملون من الذنوب، ولم تعملوه بعد، فذلك بعد تخويف لهم العقاب على كفرهم».\nوذكر ابنُ عطية (7/ 251 - 252) نحو قول مجاهد، وعزاه للحسن، ووجّهه على النحو الذي وجهه عليه ابن جرير.\nوذكر ابنُ عطية (4/ 455) قول مقاتل وقول قتادة في معناه، ورجّحهما بقوله: «هذا هو النظر». ولم يذكر مستندًا. ثم ذكر قولًا عن مجاهد أنه قال: «{ما بين أيديهم} هو الآخرة، و {ما خلفهم} عذاب الأمم». ثم علّق عليه قائلًا: «فجعل الترتيب كأنهم يسيرون مِن شيء إلى شيء، ولم يعتبر وجود الأشياء في الزمن». ثم انتقده مستندًا إلى النظائر بقوله: «وهذا النظر يكسره عليه قوله تعالى: {مُصَدِّقًا لِما بَيْنَ يَدَيْهِ مِنَ التَّوْراةِ وآتَيْناهُ الإنْجِيلَ} [المائدة: 46]، وإنما المطرد أن يقاس ما بين اليد والخلف بما يسوقه الزمن، فتأمله».", "mawaqif": [{"taliq": 5434, "mi": 0, "aya": 45, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "19/ 447", "qawl": "", "nass": "قوله تعالى: {وإذا قيل لهم اتقوا ما بين أيديكم وما خلفكم لعلكم ترحمون وما تأتيهم من آية من آيات ربهم إلا كانوا عنها معرضين} يقول -تعالى ذكره-: وإذا قيل لهؤلاء المشركين بالله، المكذبين رسوله محمدا صلى الله عليه وسلم: احذروا ما مضى بين أيديكم من نقم الله ومثلاته بمن حل ذلك به من الأمم قبلكم أن يحل مثله بكم، بشرككم وتكذيبكم رسوله {وما خلفكم} يقول: وما بعد هلاككم مما أنتم لاقوه إن هلكتم على كفركم الذي أنتم عليه", "qawaid": [], "tabi": ""}, {"taliq": 5434, "mi": 0, "aya": 45, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "مجاهد", "nass": "وهذا القول قريب المعنى من القول الذي قلنا؛ لأن معناه: اتقوا عقوبة ما بين أيديكم من ذنوبكم، وما خلفكم مما تعملون من الذنوب، ولم تعملوه بعد، فذلك بعد تخويف لهم العقاب على كفرهم", "qawaid": [], "tabi": ""}, {"taliq": 5434, "mi": 0, "aya": 45, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 251 - 252", "qawl": "مجاهد", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5434, "mi": 0, "aya": 45, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 455", "qawl": "مقاتل وقول", "nass": "هذا هو النظر", "qawaid": ["القرآن والنظائر"], "tabi": ""}]}], "47": [{"id": 5436, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 252 - 253) في معنى الآية احتمالين، فقال: «وقولهم يحتمل معنيين من التأويل: أحدهما يخرج على اختبارات لجهال العرب، فقد رُوِي أنّ أعرابيًا كان يرعى إبله، فيجعل السمان في الخصب، والمهازيل في المكان الجدب، فقيل له في ذلك، فقال: أُكْرِمُ ما أكرم الله، وأُهين ما أهان الله. فيُخَرَّج قولُ قريش على هذا المعنى، كأنهم رأوا الإمساك عمن أمسك الله عنه رزقه، ومن أمثالهم: كن مع الله على المدْبِر». والتأويل الثاني: «أن يكون كلامهم بمعنى الاستهزاء بقول محمد صلى الله عليه وسلم: إن ثَمَّ إلهًا هو الرزاق. فكأنهم قالوا: لِمَ لا يرزقك إلهك الذي تزعم؟ أي: نحن لا نطعم من لو يشاء هذا الإله الذي زعمت لأطعمه. وهذا كما يدعي إنسان أنه غني، ثم يحتاج إلى معونتك في مال، فتقول له على جهة الاحتجاج والهزء به: أتطلب معونتي وأنت غني؟! أي: على قولك».", "mawaqif": [{"taliq": 5436, "mi": 0, "aya": 47, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 252 - 253", "qawl": "", "nass": "وقولهم يحتمل معنيين من التأويل: أحدهما يخرج على اختبارات لجهال العرب، فقد روي أن أعرابيا كان يرعى إبله، فيجعل السمان في الخصب، والمهازيل في المكان الجدب، فقيل له في ذلك، فقال: أكرم ما أكرم الله، وأهين ما أهان الله. فيخرج قول قريش على هذا المعنى، كأنهم رأوا الإمساك عمن أمسك الله عنه رزقه، ومن أمثالهم: كن مع الله على المدبر", "qawaid": [], "tabi": ""}]}], "49": [{"id": 5437, "kinds": "توجيه،نقل", "text": "قال ابنُ عطية (7/ 254): «وقوله تعالى: {ولا إلى أهْلِهِمْ يَرْجِعُونَ} يحتمل تأويلات: أحدها: ولا يرجع أحد إلى منزله وأهله؛ لإعجال الأمر، بل تفيض نفسه حيثما أخذته الصيحة. والثاني: معناه: {ولا إلى أهْلِهِمْ يَرْجِعُونَ} قولًا، وهذا أبلغ في الاستعجال، وخص الأهل بالذكر لأنّ القول معهم في ذلك الوقت أهم على الإنسان من الأجنبيين، وأوكد في نفوس البشر. والثالث: تقديره: {ولا إلى أهْلِهِمْ يَرْجِعُونَ} أبدًا، فخرج هذا عن معنى وصف الاستعجال إلى معنى ذكر انقطاعهم وانبتارهم من دنياهم».", "mawaqif": [{"taliq": 5437, "mi": 0, "aya": 49, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 254", "qawl": "", "nass": "وقوله تعالى: {ولا إلى أهلهم يرجعون} يحتمل تأويلات: أحدها: ولا يرجع أحد إلى منزله وأهله؛ لإعجال الأمر، بل تفيض نفسه حيثما أخذته الصيحة. والثاني: معناه: {ولا إلى أهلهم يرجعون} قولا، وهذا أبلغ في الاستعجال، وخص الأهل بالذكر لأن القول معهم في ذلك الوقت أهم على الإنسان من الأجنبيين، وأوكد في نفوس البشر. والثالث: تقديره: {ولا إلى أهلهم يرجعون} أبدا، فخرج هذا عن معنى وصف الاستعجال إلى معنى ذكر انقطاعهم وانبتارهم من دنياهم", "qawaid": [], "tabi": ""}]}], "52": [{"id": 5438, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 256) قراءة أبي بن كعب، ونقل تعليق أبي الفتح عليها، فقال: «وفي قراءة أبي بن كعب (مَن هَبَّنا) قال أبو الفتح: ولم أر لها في اللغة أصلًا، ولا مرَّ بنا: مهبوب».", "mawaqif": [{"taliq": 5438, "mi": 0, "aya": 52, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 256", "qawl": "", "nass": "وفي قراءة أبي بن كعب (من هبنا) قال أبو الفتح: ولم أر لها في اللغة أصلا، ولا مر بنا: مهبوب", "qawaid": [], "tabi": ""}]}, {"id": 5439, "kinds": "ترجيح،نقد،نقل", "text": "ذكر ابنُ عطية (7/ 256) قول أبي بن كعب ونحوه عن قتادة ومجاهد، ثم انتقده مستندًا إلى ضعف إسناده، فقال: «ويروى عن أبي بن كعب، وقتادة، ومجاهد: أنّ جميع البشر ينامون نومة قبل الحشر. وهذا غير صحيح الإسناد». ورجّح مستندًا إلى اللغة أن ذلك على سبيل الاستعارة والتشبيه، فقال: «وإنما الوجه في قولهم: {مِن مَرْقَدِنا} أنها استعارة وتشبيه، كما تقول في قتيلٍ: هذا مرقده إلى يوم القيامة».", "mawaqif": [{"taliq": 5439, "mi": 0, "aya": 52, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 256", "qawl": "أبي بن", "nass": "ويروى عن أبي بن كعب، وقتادة، ومجاهد: أن جميع البشر ينامون نومة قبل الحشر. وهذا غير صحيح الإسناد", "qawaid": ["نقد الرواية (السند، الإسرائيليات)", "اللغة"], "tabi": ""}]}], "56": [{"id": 5444, "kinds": "نقل", "text": "ذكر ابنُ كثير (11/ 369) قول ابن عباس وغيره، ثم علّق، فقال: «قال ابن عباس، ومجاهد وعكرمة، ومحمد بن كعب، والحسن، وقتادة، والسُدِّيّ، وخصيف: {الأرائك} هي السرر تحت الحجال. قلت: نظيره في الدنيا هذه التخوت تحت البشاخين».", "mawaqif": [{"taliq": 5444, "mi": 0, "aya": 56, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 369", "qawl": "ابن عباس", "nass": "قال ابن عباس، ومجاهد وعكرمة، ومحمد بن كعب، والحسن، وقتادة، والسدي، وخصيف: {الأرائك} هي السرر تحت الحجال. قلت: نظيره في الدنيا هذه التخوت تحت البشاخين", "qawaid": [], "tabi": ""}]}, {"id": 5445, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 258): «و {الأَرائِكِ}: السرر المفروشة، قال بعض الناس: من شروطها أن تكون عليها، حجلة وإلا فليست بأريكة، وبذلك قيدها ابن عباس ومجاهد والحسن وعكرمة. وقال بعضهم: الأريكة: السرير؛ كان عليه حجلة أو لم يكن».", "mawaqif": [{"taliq": 5445, "mi": 0, "aya": 56, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 258", "qawl": "", "nass": "و {الأرائك}: السرر المفروشة، قال بعض الناس: من شروطها أن تكون عليها، حجلة وإلا فليست بأريكة، وبذلك قيدها ابن عباس ومجاهد والحسن وعكرمة. وقال بعضهم: الأريكة: السرير؛ كان عليه حجلة أو لم يكن", "qawaid": [], "tabi": ""}]}], "58": [{"id": 5446, "kinds": "توجيه،تعليق،نقل،استدلال", "text": "ذكر ابنُ جرير (19/ 466 - 467) هذه القراءة، وعلّق عليها، فقال: «وقد ذكر أنها في قراءة عبد الله: (سلامًا قولًا) على أن الخبر متناهٍ عند قوله: {ولهم ما يدعون}، ثم نصب (سلامًا) على التوكيد، بمعنى: مسلمًا قولًا».\nوأورد في رفع {سلام} في قراءة من قرأها كذلك وجهين، فقال: «في رفع {سلام} وجهان في قول بعض نحويي الكوفة: أحدهما: أن يكون خبرًا لـ {ما يدعون}، فيكون معنى الكلام: ولهم ما يدعون مسلم لهم خالص. وإذا وجه معنى الكلام إلى ذلك كان القول حينئذ منصوبًا توكيدًا خارجًا مِن السلام، كأنه قيل: ولهم فيها ما يدعون مسلم خالص حقًّا، كأنه قيل: قاله قولًا. والوجه الثاني: أن يكون قوله: {سلام} مرفوعًا على المدح، بمعنى: هو سلامٌ لهم قولًا مِن الله». ثم قال: «والذي هو أولى بالصواب على ما جاء به الخبر عن محمد بن كعب القرظي أن يكون {سلام} خبرًا لقوله: {ولهم ما يدعون}؛ فيكون معنى ذلك: ولهم فيها ما يدعون، وذلك هو سلام من الله عليهم، بمعنى: تسليم من الله، ويكون {سلام} ترجمة {ما يدعون}، ويكون القول خارجًا من قوله: سلام». واستدل ابنُ جرير على هذا بقول عمر بن عبد العزيز وقول محمد بن كعب الآتيين، ثم قال (19/ 469) معلّقًا عليه: «فهذا القول الذي قاله محمد بن كعب ينبئ عن أن {سلام} بيان عن قوله: {ما يدعون}، وأن القول خارج من السلام».", "mawaqif": [{"taliq": 5446, "mi": 0, "aya": 58, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 466 - 467", "qawl": "", "nass": "وقد ذكر أنها في قراءة عبد الله: (سلاما قولا) على أن الخبر متناه عند قوله: {ولهم ما يدعون}، ثم نصب (سلاما) على التوكيد، بمعنى: مسلما قولا", "qawaid": [], "tabi": ""}, {"taliq": 5446, "mi": 0, "aya": 58, "alam": "ابن جرير", "fil": "استدل", "kind": "استدلال", "ref": "", "qawl": "عمر بن", "nass": "فهذا القول الذي قاله محمد بن كعب ينبئ عن أن {سلام} بيان عن قوله: {ما يدعون}، وأن القول خارج من السلام", "qawaid": [], "tabi": ""}]}, {"id": 5447, "kinds": "تعليق،نقل", "text": "ذكر ابنُ كثير (11/ 370) قول ابن عباس، وعلّق عليه، فقال: «وهذا الذي قاله ابن عباس كقوله تعالى: {تحيتهم يوم يلقونه سلام} [الأحزاب: 44]».", "mawaqif": [{"taliq": 5447, "mi": 0, "aya": 58, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 370", "qawl": "ابن عباس", "nass": "وهذا الذي قاله ابن عباس كقوله تعالى: {تحيتهم يوم يلقونه سلام} [الأحزاب: 44]", "qawaid": [], "tabi": ""}]}], "62": [{"id": 5448, "kinds": "خلاف،ترجيح،تعليق،نقل", "text": "ذكر ابنُ جرير (19/ 471) في قوله: {جبلا} ثلاث قراءات، فقال: «واختلف القراء في قراءة ذلك، فقرأته عامة قراء المدينة وبعض الكوفيين: {جِبلًّا} بكسر الجيم وتشديد اللام، وكان بعض المكيين وعامة قراء الكوفة يقرؤونه: (جُبُلًا) بضم الجيم والباء وتخفيف اللام. وكان بعض قراء البصرة يقرؤه: «جُبْلًا» بضم الجيم وتسكين الباء». ثم علّق بقوله: «وكل هذه لغات معروفات». ثم رجّح قراءة من قرأ ذلك بكسر الجيم وتشديد اللام، وقراءة مَن قرأ ذلك بضم الجيم وتخفيف اللام مستندًا للإجماع، فقال: «غير أني لا أحب القراءة في ذلك إلا بإحدى القراءتين اللتين إحداهما بكسر الجيم وتشديد اللام، والأخرى بضم الجيم والباء وتخفيف اللام؛ لأن ذلك هو القراءة التي عليها عامة قرّاء الأمصار».", "mawaqif": [{"taliq": 5448, "mi": 0, "aya": 62, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 471", "qawl": "", "nass": "واختلف القراء في قراءة ذلك، فقرأته عامة قراء المدينة وبعض الكوفيين: {جبلا} بكسر الجيم وتشديد اللام، وكان بعض المكيين وعامة قراء الكوفة يقرؤونه: (جبلا) بضم الجيم والباء وتخفيف اللام. وكان بعض قراء البصرة يقرؤه: «جبلا", "qawaid": ["الإجماع"], "tabi": ""}]}], "67": [{"id": 5449, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 262 ط: دار الكتب العلمية) قول قتادة وقول الحسن، ثم علّق عليهما، فقال: «وقال الحسن بن أبي الحسن، وقتادة: أراد الأعين حقيقة، والمعنى: لأعميناهم فلا يرون كيف يمشون. ويؤيد هذا مجانسة المسخ للعمى الحقيقي».", "mawaqif": [{"taliq": 5449, "mi": 0, "aya": 67, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 262 ط: دار الكتب العلمية", "qawl": "قتادة وقول", "nass": "وقال الحسن بن أبي الحسن، وقتادة: أراد الأعين حقيقة، والمعنى: لأعميناهم فلا يرون كيف يمشون. ويؤيد هذا مجانسة المسخ للعمى الحقيقي", "qawaid": [], "tabi": ""}]}, {"id": 5451, "kinds": "توجيه،نقل", "text": "ذكر ابنُ جرير (19/ 476) قول مجاهد، وقدّم له بقوله: «وقوله: {فأنى يبصرون} يقول: فأي وجه يبصرون أن يسلكوه من الطرق، وقد طمسنا على أعينهم؟!». ثم قال: «وقال الذين وجهوا تأويل قوله: {ولو نشاء لطمسنا على أعينهم} إلى أنه معني به: العمى عن الهدى؛ تأويل قوله: {فأنى يبصرون}: فأنى يهتدون للحق». وذكر قولي ابن عباس.", "mawaqif": [{"taliq": 5451, "mi": 0, "aya": 67, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 476", "qawl": "مجاهد", "nass": "وقوله: {فأنى يبصرون} يقول: فأي وجه يبصرون أن يسلكوه من الطرق، وقد طمسنا على أعينهم؟!", "qawaid": [], "tabi": ""}]}], "69": [{"id": 5454, "kinds": "بيان،تعليق،نقل", "text": "ذكر ابنُ كثير (11/ 379 - 380) بعض الآثار التي أفادت قول النبي صلى الله عليه وسلم بعض الأشعار، ثم علّق قائلًا: «وكل هذا لا ينافي كونه صلى الله عليه وسلم ما علم شعرًا ولا ينبغي له؛ فإن الله تعالى إنما علمه القرآن العظيم، الذي لا يأتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد، وليس هو بشعرٍ كما زعمه طائفة مِن جهلة كفار قريش، ولا كهانة، ولا مفتعل، ولا سحر يؤثر، كما تنوعت فيه أقوال الضلال وآراء الجهال. وقد كانت سجيته صلى الله عليه وسلم تأبى صناعة الشعر طبعًا وشرعًا».", "mawaqif": [{"taliq": 5454, "mi": 0, "aya": 69, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 379 - 380", "qawl": "النبي صلى", "nass": "وكل هذا لا ينافي كونه صلى الله عليه وسلم ما علم شعرا ولا ينبغي له؛ فإن الله تعالى إنما علمه القرآن العظيم، الذي لا يأتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد، وليس هو بشعر كما زعمه طائفة من جهلة كفار قريش، ولا كهانة، ولا مفتعل، ولا سحر يؤثر، كما تنوعت فيه أقوال الضلال وآراء الجهال. وقد كانت سجيته صلى الله عليه وسلم تأبى صناعة الشعر طبعا وشرعا", "qawaid": [], "tabi": ""}]}], "75": [{"id": 5455, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 266) في عود الضمير من قوله: {يستطيعون} احتمالين، وصححهما، فقال: «ويحتمل أن يكون الضمير في {يَسْتَطِيعُونَ} للكفار، وفي {نصْرَهم} للأصنام، ويحتمل الأمر عكس ذلك؛ لأن الوجهين صحيحان في المعنى».", "mawaqif": [{"taliq": 5455, "mi": 0, "aya": 75, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 266", "qawl": "", "nass": "ويحتمل أن يكون الضمير في {يستطيعون} للكفار، وفي {نصرهم} للأصنام، ويحتمل الأمر عكس ذلك؛ لأن الوجهين صحيحان في المعنى", "qawaid": [], "tabi": ""}]}], "77": [{"id": 5457, "kinds": "نقد،توجيه،بيان،نقل", "text": "انتقد ابن عطية (7/ 267) مستندًا إلى أحوال النزول والدلالة العقلية ما أفاده هذا الأثر عن ابن عباس من كون الآية نازلة في عبد الله بن أبي، فقال: «وهو وهمٌ ممن نسبه إلى ابن عباس؛ لأن السورة مكية، والآية مكية بإجماع، ولأن عبد الله بن أبي لم يجاهر قط هذه المجاهرة، واسْمُ أُبي هو الذي خلط على الرواة؛ لأن الصحيح هو ما رواه ابن وهب عن مالك، وقاله ابن إسحاق وغيره: من أن أبي بن خلف أخا أمية بن خلف هو الذي جاء بالعظم الرميم بمكة ففته في وجه النبي صلى الله عليه وسلم، وقال: من يحيي هذا، يا محمد؟».\nوبنحوه قال ابنُ كثير (11/ 384).", "mawaqif": [{"taliq": 5457, "mi": 0, "aya": 77, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 267", "qawl": "", "nass": "وهو وهم ممن نسبه إلى ابن عباس؛ لأن السورة مكية، والآية مكية بإجماع، ولأن عبد الله بن أبي لم يجاهر قط هذه المجاهرة، واسم أبي هو الذي خلط على الرواة؛ لأن الصحيح هو ما رواه ابن وهب عن مالك، وقاله ابن إسحاق وغيره: من أن أبي بن خلف أخا أمية بن خلف هو الذي جاء بالعظم الرميم بمكة ففته في وجه النبي صلى الله عليه وسلم، وقال: من يحيي هذا، يا محمد؟", "qawaid": ["سبب النزول وأحواله", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5457, "mi": 0, "aya": 77, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "11/ 384", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}]}, {"id": 5458, "kinds": "نقد،نقل", "text": "ذكر ابنُ كثير (11/ 384) الاختلاف الوارد في نزول الآية، وفيمن عني بها، ثم قال معلّقًا: «وعلى كل تقدير سواء كانت هذه الآيات قد نزلت في أبي بن خلف، أو في العاص بن وائل، أو فيهما، فهي عامة في كل مَن أنكر البعث. والألف واللام في قوله: {أولم ير الإنسان} للجنس، يعم كل منكر للبعث».", "mawaqif": [{"taliq": 5458, "mi": 0, "aya": 77, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 384", "qawl": "", "nass": "وعلى كل تقدير سواء كانت هذه الآيات قد نزلت في أبي بن خلف، أو في العاص بن وائل، أو فيهما، فهي عامة في كل من أنكر البعث. والألف واللام في قوله: {أولم ير الإنسان} للجنس، يعم كل منكر للبعث", "qawaid": [], "tabi": ""}]}]}, "athar": {"64896": {"num": 64896, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس ="}, "64897": {"num": 64897, "aya": 67, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "وقتادة بن دعامة ="}, "64771": {"num": 64771, "aya": 52, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أُبَيّ بن كعب، قال: ينامون نومةً قبل البعث، فيجدون لذلك راحة، فيقولون: (يا ويْلَنا مَن هَبَّنا مِن مَّرْقَدِنا)؟!."}, "64772": {"num": 64772, "aya": 52, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أُبَيّ بن كعب -من طريق الحسن- في قوله: {يا ويْلَنا مَن بَعَثَنا مِن مَرْقَدِنا}، قال: ينامون قبل البعث نَوْمَةً."}, "64773": {"num": 64773, "aya": 52, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "قال أُبَيّ بن كعب ="}, "64900": {"num": 64900, "aya": 67, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أبي رجاء- في قوله: {ولَوْ نَشاءُ لَطَمَسْنا}، قال: لو شاء الله لتركهم عُمْيًا يَتَرَدَّدون."}, "64901": {"num": 64901, "aya": 67, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {ولَوْ نَشاءُ لَطَمَسْنا عَلى أعْيُنِهِمْ"}, "64776": {"num": 64776, "aya": 52, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال قتادة بن دعامة -من طريق سعيد بن بشير-: إنّه لا يُفَتَّر عن أهل القبور عذابُ القبر إلا فيما بين نفخة الصعق ونفخة البعث، فلذلك يقول الكافر حين يبعث: {يا ويْلَنا مَن بَعَثَنا مِن مَرْقَدِنا} يعني: تلك الفترة، فيقول المؤمن: {هَذا ما وعَدَ الرَّحْمَنُ وصَدَقَ المُرْسَلُونَ}."}, "64777": {"num": 64777, "aya": 52, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد بن أبي عروبة- قال: الكافر إلى جنب المؤمن، فإذا أصابته النفخةُ قال الكافر: {يا ويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون}."}, "64905": {"num": 64905, "aya": 67, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "فاسْتَبَقُوا الصِّراطَ", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: {فاسْتَبَقُوا الصِّراطَ}، أي: الطريق."}, "64908": {"num": 64908, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {فَأَنّى يُبْصِرُونَ}، قال: فكيف يهتدون؟!."}, "64909": {"num": 64909, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية- {فَأَنّى يُبْصِرُونَ}، يقول: لا يبصرون الحقَّ."}, "64782": {"num": 64782, "aya": 52, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قوله: {يا ويْلَنا مَن بَعَثَنا مِن مَرْقَدِنا} قال: الكافرون يقولونه، {هَذا ما وعَدَ الرَّحْمَنُ} مما سرَّ المؤمنون، يقولون هذا حين البعث."}, "64783": {"num": 64783, "aya": 52, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- قال: للكفار هجْعة يجدون فيها طعم النوم قبل يوم القيامة، فإذا صِيح بأهل القبور يقول الكافر: {يا ويْلَنا مَن بَعَثَنا مِن مَرْقَدِنا}؟ فيقول المؤمن إلى جنبه: {هَذا ما وعَدَ الرَّحْمَنُ وصَدَقَ المُرْسَلُونَ}."}, "64528": {"num": 64528, "aya": 25, "qail": "وهب بن منبه", "tabaqa": "تابعي", "bab": "", "text": "ووهب بن مُنَبِّه -من طريق ابن إسحاق-: قال لهم: {وما لِيَ لا أعْبُدُ الَّذِي فَطَرَنِي} إلى قوله: {فاسْمَعُونِ}، وثبوا عليه وثبةَ رجلٍ واحد، فقتلوه، واستضعفوه لضعفه وسقمه، ولم يكن أحد يدفع عنه."}, "64785": {"num": 64785, "aya": 52, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {يا ويْلَنا مَن بَعَثَنا مِن مَرْقَدِنا} قال: أولها للكفار، وآخرها للمسلمين؛ قال الكفار: {يا ويْلَنا مَن بَعَثَنا مِن مَرْقَدِنا}؟ وقال المسلمون: {هَذا ما وعَدَ الرَّحْمَنُ وصَدَقَ المُرْسَلُونَ}."}, "64786": {"num": 64786, "aya": 52, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "وعن أُبَيّ بن كعب -من طريق الحسن-، مثل ذلك."}, "64531": {"num": 64531, "aya": 25, "qail": "وهب بن منبه", "tabaqa": "تابعي", "bab": "", "text": "عن وهب بن مُنَبِّه -من طريق ابن إسحاق- {إنِّي آمَنتُ بِرَبِّكُمْ فاسْمَعُونِ}: إني آمنت بربكم الذي كفرتم به، فاسمعوا قولي."}, "64532": {"num": 64532, "aya": 25, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {يا قَوْمِ اتَّبِعُوا المُرْسَلِينَ * اتَّبِعُوا مَن لا يَسْأَلُكُمْ أجْرًا وهُمْ مُهْتَدُونَ} حتى بلغ: {فاسْمَعُونِ}، قال: فرجموه بالحجارة، فجعل يقول: ربِّ، اهدِ قومي؛ فإنهم لا يعلمون. فلم يزالوا يرجموه حتى قتلوه."}, "64911": {"num": 64911, "aya": 67, "qail": "الحسن", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن ="}, "64913": {"num": 64913, "aya": 67, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: {فَأَنّى يُبْصِرُونَ} فكيف يُبِصرون إذا أغشيناهم؟!."}, "64915": {"num": 64915, "aya": 67, "qail": "الحسن", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن الحسن -من طريق إسماعيل-: {لَمَسَخْناهُمْ عَلى مَكانَتِهِمْ}، وقد اختلف فيها عنه."}, "64917": {"num": 64917, "aya": 67, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق أبي رجاء- {ولَوْ نَشاءُ لَمَسَخْناهُمْ عَلى مَكانَتِهِمْ}، قال: لو نشاء لأقعدناهم."}, "64919": {"num": 64919, "aya": 67, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {ولَوْ نَشاءُ لَمَسَخْناهُمْ عَلى مَكانَتِهِمْ} قال: لو نشاء لجعلناهم كُسحًا لا يقومون، {فَما اسْتَطاعُوا مُضِيًّا ولا يَرْجِعُونَ} قال: فلم يستطيعوا أن يتقدموا ولا يتأخروا."}, "64916": {"num": 64916, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {ولَوْ نَشاءُ لَمَسَخْناهُمْ} قال: أهلكناهم، {عَلى مَكانَتِهِمْ} قال: في مساكنهم."}, "64539": {"num": 64539, "aya": 26, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- قال: فلم يزالوا يرجموه حتى قتلوه، فدخل الجنة، فقال: { … يا لَيْتَ قَوْمِي يَعْلَمُونَ * بِما غَفَرَ لِي رَبِّي} حتى بلغ: {إنْ كانَتْ إلّا صَيْحَةً واحِدَةً}. قال: فما نُوظِرُوا بعد قتلهم إيّاه حتى أخذتهم صيحة واحدة، فإذا هم خامدون."}, "64540": {"num": 64540, "aya": 26, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {قِيلَ ادْخُلِ الجَنَّةَ} فلما دخلها {قالَ يا لَيْتَ قَوْمِي يَعْلَمُونَ}. قال: فلا تلقى المؤمنَ إلا ناصحًا، ولا تلقاه غاشًّا، فلما عاين مِن كرامة الله قال: {يا لَيْتَ قَوْمِي يَعْلَمُونَ * بِما غَفَرَ لِي رَبِّي وجَعَلَنِي مِنَ المُكْرَمِينَ}. تمنى على الله أن يعلم قومُه ما عايَن مِن كرامة الله، وما هم عليه."}, "64797": {"num": 64797, "aya": 55, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق شقيق بن سلمة- في قوله: {إنَّ أصْحابَ الجَنَّةِ اليَوْمَ فِي شُغُلٍ فاكِهُونَ}، قال: شَغَلهم افتضاضُ العذارى."}, "64286": {"num": 64286, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: كان النبيُّ صلى الله عليه وسلم يقرأ في المسجد، فيجهر بالقراءة، حتى تأذّى به ناسٌ مِن قريش، حتى قاموا ليأخذوه، وإذا أيديهم مجموعةٌ إلى أعناقهم، وإذا هم عُمْيٌ لا يبصرون، فجاءوا إلى النبي صلى الله عليه وسلم، فقالوا: ننشدك اللهَ والرحمَ، يا محمد. قال: ولم يكن بطنٌ مِن بطون قريش إلا وللنبيِّ صلى الله عليه وسلم فيهم قرابة، فدعا النبيُّ صلى الله عليه وسلم حتى ذهب ذلك عنهم؛ فنزلت: {يس * والقُرْآنِ الحَكِيمِ} إلى قوله: {أمْ لَمْ تُنْذِرْهُمْ لا يُؤْمِنُونَ}. قال: فلم يؤمن مِن ذلك النفر أحدٌ."}, "64798": {"num": 64798, "aya": 55, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {فِي شُغُلٍ فاكِهُونَ}، قال: في افتضاض الأبكار."}, "64544": {"num": 64544, "aya": 28, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال الله: {وما أنْزَلْنا عَلى قَوْمِهِ مِن بَعْدِهِ مِن جُنْدٍ مِنَ السَّماءِ}: رسالة."}, "64289": {"num": 64289, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، قال: {يس} محمد صلى الله عليه وسلم. وفي لفظ، قال: يا محمد."}, "64290": {"num": 64290, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- قوله: {يس}، قال: فإنّه قسم أقسمه الله، وهو من أسماء الله."}, "64291": {"num": 64291, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {يس}، قال: يا إنسان، بالحَبَشِيَّة."}, "64292": {"num": 64292, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {يس}، قال: يا إنسان."}, "64547": {"num": 64547, "aya": 28, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وما أنْزَلْنا عَلى قَوْمِهِ مِن بَعْدِهِ مِن جُنْدٍ مِنَ السَّماءِ وما كُنّا مُنْزِلِينَ} قال: فلا، واللهِ، ما عاتب اللهُ قومَه بعد قتله، {إنْ كانَتْ إلّا صَيْحَةً واحِدَةً فَإذا هُمْ خامِدُونَ}."}, "64801": {"num": 64801, "aya": 55, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {فِي شُغُلٍ فاكِهُونَ}، قال: ضَرْب الأوتار."}, "64802": {"num": 64802, "aya": 55, "qail": "سعيد بن المسيب", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن المسيب -من طريق وائل بن داود- في قوله: {إنَّ أصْحابَ الجَنَّةِ اليَوْمَ فِي شُغُلٍ فاكِهُونَ}، قال: في افتضاض العذارى."}, "64804": {"num": 64804, "aya": 55, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {إنَّ أصْحابَ الجَنَّةِ اليَوْمَ فِي شُغُلٍ}، قال: مِن النِّعمة."}, "64806": {"num": 64806, "aya": 55, "qail": "إسماعيل بن أبي خالد", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل بن أبي خالد -من طريق أبان بن تغلب- {إنَّ أصْحابَ الجَنَّةِ} الآية، قال: في شُغل عمّا يلقى أهلُ النار."}, "64298": {"num": 64298, "aya": 1, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال: {يس}: مفتاح كلام، افتتح الله به كلامه."}, "64814": {"num": 64814, "aya": 55, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {فاكِهُونَ}، قال: فرِحون."}, "64431": {"num": 64431, "aya": 13, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد-: هي أنطاكيةُ."}, "64304": {"num": 64304, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {يس}، قال: كل هجاء في القرآن اسمٌ مِن أسماء القرآن."}, "64305": {"num": 64305, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق عثمان- قال: {يس} يا إنسان، والسين حرف من اسم الإنسان، يقول النبي صلى الله عليه وسلم: يا إنسان."}, "64688": {"num": 64688, "aya": 42, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ}، قال: هي السفن، جُعِلَت مِن بعد سفينة نوحٍ على مِثلها."}, "64689": {"num": 64689, "aya": 42, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ}: يعني: الإبل؛ خلقها الله كما رأيتَ، فهي سُفُن البر، يحملون عليها ويركبونها."}, "64691": {"num": 64691, "aya": 42, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ}، قال: الأنعام."}, "64815": {"num": 64815, "aya": 55, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {فاكِهُونَ}، قال: مُعجبون."}, "64438": {"num": 64438, "aya": 13, "qail": "وهب بن منبه", "tabaqa": "تابعي", "bab": "", "text": "قال وهب بن مُنَبِّه: {إذْ أرْسَلْنا إلَيْهِمُ اثْنَيْنِ}، اسمهما: يوحنا، وبولس."}, "64439": {"num": 64439, "aya": 13, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله تعالى: {إذْ أرْسَلْنا إلَيْهِمُ اثْنَيْنِ}، قال: بلغني: أنّ عيسى ابن مريم بَعَث إلى أهل القرية -وهي أنطاكية- رجلين مِن الحواريين، وأَتْبَعَهم بثالث."}, "64694": {"num": 64694, "aya": 42, "qail": "أبي مالك غزوان الغفاري", "tabaqa": "تابعي", "bab": "", "text": "عن أبي مالك غزوان الغفاري، في قوله: {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ}، قال: السفن التي في البحر، والأنهار التي يركب الناس فيها."}, "64695": {"num": 64695, "aya": 42, "qail": "أبي مالك غزوان الغفاري", "tabaqa": "تابعي", "bab": "", "text": "عن أبي مالك غزوان الغفاري -من طريق السُدِّيّ- في قوله: {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ}، قال: السفن الصغار، ألا ترى أنه قال: {وإنْ نَشَأْ نُغْرِقْهُمْ فَلا صَرِيخَ لَهُمْ}؟!."}, "64698": {"num": 64698, "aya": 42, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح باذام، في قوله: {حَمَلْنا ذُرِّيَّتَهُمْ فِي الفُلْكِ المَشْحُونِ} قال: سفينة نوح، {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ} هذه السفن مثل خشبها وصنعتها."}, "64699": {"num": 64699, "aya": 42, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح باذام -من طريق شعبة، عن إسماعيل- في قوله: {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ}، قال: السفن الصغار."}, "64700": {"num": 64700, "aya": 42, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ}، قال: يعني: السفن الصغار."}, "64701": {"num": 64701, "aya": 42, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ}، قال: هي السُّفُن التي يُنتَفَع بها."}, "64318": {"num": 64318, "aya": 6, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، في قوله: {لِتُنْذِرَ قَوْمًا ما أُنْذِرَ آباؤُهُمْ}: أي: ما أُنذر الناسُ قبلهم."}, "64319": {"num": 64319, "aya": 6, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {لِتُنْذِرَ قَوْمًا ما أُنْذِرَ آباؤُهُمْ}، قال: قال بعضهم: {لِتُنْذِرَ قَوْمًا ما أُنْذِرَ آباؤُهُمْ} ما أُنذِر الناسُ مِن قبلهم. وقال بعضهم: {لِتُنْذِرَ قَوْمًا ما أُنْذِرَ آباؤُهُمْ}، أي: هذه الأمة لم يأتهم نذيرٌ حتى جاءهم محمدٌ صلى الله عليه وسلم."}, "64703": {"num": 64703, "aya": 42, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وخَلَقْنا لَهُمْ مِن مِثْلِهِ ما يَرْكَبُونَ}، قال: وهي هذه الفلك."}, "64983": {"num": 64983, "aya": 75, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {لا يَسْتَطِيعُونَ نَصْرَهُمْ}، قال: نصر الآلهة، ولا تستطيع الآلهة نصْرهم."}, "64990": {"num": 64990, "aya": 75, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وهُمْ لَهُمْ جُنْدٌ مُحْضَرُونَ}، قال: المشركون يغضبون للآلهة في الدنيا، وهي لا تسوق إليهم خيرًا، ولا تدفع عنهم سوءًا، إنما هي أصنام."}, "64895": {"num": 64895, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {ولَوْ نَشاءُ لَطَمَسْنا عَلى أعْيُنِهِمْ}، قال: أعميناهم، وأضللناهم عن الهدى."}, "64617": {"num": 64617, "aya": 38, "qail": "أبى ذر الغفاري", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أبى ذرٍّ الغفاري، قال: كنت آخذ بيد رسول الله صلى الله عليه وسلم، ونحن نتماشى جميعًا نحو المغرب، وقد طَفَلَت الشمس، فما زلنا ننظر إليها حتى غابت، قال: قلت: يا رسول الله، أين تغرب؟ قال: «تغرب في السماء ثم ترفع مِن سماء إلى سماء، حتى ترفع إلى السماء السابعة العليا، حتى تكون تحت العرش، فتخر ساجدة، فتسجد معها الملائكة الموكلون بها، ثم تقول: يا رب، مِن أين تأمرني أن أطلع؛ أمِن مغربي أم مِن مطلعي؟». قال: فذلك قوله عز وجل: {والشمس تجرى لمستقر لها} حيث تحبس تحت العرش {ذلك تقدير العزيز العليم}. قال: يعني: ذلك صنع الرب العزيز في ملكه العليم بخلقه. قال: فيأتيها جبرائيل عليه السلام بحلة ضوء مِن نور العرش، على مقادير ساعات النهار في طوله في الصيف أو قصره في الشتاء أو ما بين ذلك في الخريف والربيع. قال: فتلبس تلك الحُلَّة كما يلبس أحدكم ثيابه، ثم ينطلق بها في جو السماء حتى تطلع من مطالعها. قال النبي صلى الله عليه وسلم: «فكأنها قد حُبست مقدار ثلاث ليال، ثم لا تُكسى ضوءًا، وتُؤمر أن تطلع من مغربها». فذلك قوله عز وجل: {إذ الشمس كورت} [التكوير: 1]. قال: والقمر كذلك في مطلعه ومجراه في أفق السماء ومغربه وارتفاعه إلى السماء السابعة العليا، ومحبسه تحت العرش وسجوده واستئذانه، ولكن جبرائيل عليه السلام يأتيه بالحلة من نور الكرسي. قال: فذلك قوله عز وجل: {جعل الشمس ضياء والقمر نورا} [يونس: 5]. قال أبو ذر: ثم عدلت مع رسول الله صلى الله عليه وسلم، فصلَّيْنا المغرب."}, "65018": {"num": 65018, "aya": 79, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن ابن عباس، عن النبي صلى الله عليه وسلم، قال: «قال الله: كذَّبني ابنُ آدم، ولم يكن له ذلك، وشتمني، ولم يكن له ذلك؛ فأمّا تكذيبه إيّاي فزعم أنّي لا أقدر أن أعيده كما كان، وأما شتمه إياي فقوله: لي ولد، فسبحاني أن أتخذ صاحبة أو ولدًا»."}, "64767": {"num": 64767, "aya": 52, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن أُبَيّ بن كعب، أنه قرأ: (يا ويْلَنا مَن هَبَّنا مِن مَّرْقَدِنا)."}}, "n_athar": {"0": 10, "1": 23, "2": 5, "4": 3, "6": 7, "7": 4, "8": 31, "9": 23, "10": 3, "11": 3, "12": 39, "13": 16, "14": 13, "15": 7, "18": 11, "19": 21, "20": 16, "21": 5, "22": 7, "25": 11, "26": 8, "28": 6, "29": 17, "30": 14, "31": 6, "32": 6, "33": 2, "34": 2, "35": 5, "36": 4, "37": 5, "38": 17, "39": 16, "40": 30, "41": 15, "42": 17, "43": 5, "44": 3, "45": 8, "46": 2, "47": 7, "48": 2, "49": 19, "51": 16, "52": 24, "53": 4, "54": 2, "55": 25, "56": 13, "57": 3, "58": 9, "59": 10, "60": 7, "61": 2, "62": 11, "63": 2, "65": 15, "66": 1, "67": 27, "68": 12, "69": 19, "70": 8, "71": 6, "72": 8, "73": 3, "74": 4, "75": 12, "76": 3, "77": 18, "78": 2, "79": 3, "80": 4, "81": 4, "83": 2}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});